function assessmentMetrics(x){
 const seed=Number(x.id||1);
 if(/personnalit|ipip|big five/i.test(x.type)) return [
  ['Ouverture',68+(seed%4)*4],['Conscience',76+(seed%3)*4],['Extraversion',54+(seed%5)*3],['Agréabilité',72+(seed%4)*3],['Stabilité',64+(seed%5)*4]
 ];
 if(/verbal/i.test(x.type)) return [['Compréhension',78],['Vocabulaire',72],['Logique verbale',81],['Attention',69],['Vitesse',74]];
 if(/numérique/i.test(x.type)) return [['Calcul',74],['Analyse',82],['Raisonnement',78],['Attention',71],['Vitesse',67]];
 return [['Logique',82-(seed%3)*4],['Analyse',78+(seed%4)*3],['Attention',71+(seed%5)*3],['Mémoire',68+(seed%4)*4],['Vitesse',74+(seed%3)*3]];
}
