function radarSvg(metrics,ariaLabel='Radar des dimensions du test',color='#1687c4'){
 const cx=100,cy=100,max=70,point=(value,i)=>{const angle=(Math.PI*2*i/metrics.length)-Math.PI/2;const r=max*value/100;return `${(cx+Math.cos(angle)*r).toFixed(1)},${(cy+Math.sin(angle)*r).toFixed(1)}`};
 const rings=[20,40,60,80,100].map(v=>`<polygon points="${metrics.map((_,i)=>point(v,i)).join(' ')}" fill="none" stroke="#dce8f1" stroke-width="1"/>`).join('');
 const axes=metrics.map((_,i)=>`<line x1="${cx}" y1="${cy}" x2="${point(100,i).split(',')[0]}" y2="${point(100,i).split(',')[1]}" stroke="#dce8f1" stroke-width="1"/>`).join('');
 const labels=metrics.map(([label],i)=>{const angle=(Math.PI*2*i/metrics.length)-Math.PI/2;const r=88;return `<text x="${(cx+Math.cos(angle)*r).toFixed(1)}" y="${(cy+Math.sin(angle)*r).toFixed(1)}" text-anchor="middle" dominant-baseline="middle" fill="#60758a" font-size="8">${E(label)}</text>`}).join('');
 return `<div class="assessment-radar"><svg viewBox="0 0 200 200" role="img" aria-label="${E(ariaLabel)}">${rings}${axes}<polygon points="${metrics.map(([,value],i)=>point(value,i)).join(' ')}" fill="${color}33" stroke="${color}" stroke-width="2"/>${metrics.map(([,value],i)=>{const [px,py]=point(value,i).split(',');return `<circle cx="${px}" cy="${py}" r="3" fill="${color}"/>`}).join('')}${labels}</svg></div>`;
}
