function login(){return `<div class="login-page"><div class="login-left"><form class="login-form" id="login-form"><div class="mk-login-logo-box"><img class="logo" src="assets/mklean-logo.png" alt="MKLEAN Recruiting"></div><div class="eyebrow">PLATEFORME RH INTELLIGENTE</div><h1>Heureux de vous retrouver.</h1><p>Connectez-vous à votre espace intelligent de gestion des candidatures.</p><div class="field" style="margin-bottom:15px"><label>Adresse email</label><input class="input" type="email" value="demo@mklean.example" required></div><div class="field" style="margin-bottom:10px"><label>Mot de passe</label><input class="input" id="password" type="password" value="demo1234" required></div><div style="display:flex;justify-content:space-between;margin-bottom:23px;align-items:center"><label style="font-size:11px;color:#75869a"><input type="checkbox" checked> Se souvenir de moi</label><a href="#" class="link" data-action="password-info">Mot de passe oublié ?</a></div><button type="submit" class="btn btn-primary btn-block" style="height:45px">${ico('arrow-right')} Accéder à la plateforme</button><div class="notice" style="margin-top:23px">${ico('info')} Compte de démonstration prérempli. Aucune donnée réelle n’est transmise.</div><div class="footnote">© 2026 CLV TECH · Smart Systems & Software</div></form></div><div class="login-right"><div class="login-content"><div class="eyebrow" style="color:#6fe3ec">L'INTELLIGENCE AU SERVICE DU RECRUTEMENT</div><h2>Donnez du sens à chaque parcours professionnel.</h2><p>Centralisez, analysez et valorisez les candidatures grâce au matching sémantique et au séquenceur visuel des carrières.</p><div class="login-tiles"><div class="login-tile">${ico('brain')}<strong>Matching intelligent</strong><small>Rapprochez les talents des opportunités.</small></div><div class="login-tile">${ico('timeline')}<strong>Parcours en séquences</strong><small>Explorez chaque étape du parcours.</small></div><div class="login-tile">${ico('database')}<strong>CVthèque centralisée</strong><small>Des profils structurés et accessibles.</small></div><div class="login-tile">${ico('shield')}<strong>Approche responsable</strong><small>Traçabilité et validation humaine.</small></div></div></div></div></div>`}
function dashboard(){const total=db.candidates.length,jobs=db.jobs.filter(j=>j.status==='Active').length,validated=db.candidates.filter(c=>c.validated).length,unverified=total-validated;const stats=[['Candidats enregistrés',total,'users','','Échantillon fictif'],['CV analysés',total,'file','teal','Profils structurés'],['Offres actives',jobs,'briefcase','purple','Recrutement en cours'],['Profils à vérifier',unverified,'shield','amber','Validation humaine']];
return `<div class="hero"><div style="position:relative;z-index:2"><div style="font-size:10px;letter-spacing:1.7px;font-weight:800;color:#9bdef2;margin-bottom:9px">BIENVENUE SUR MKLEAN TALENT AI ✦</div><h2>Vos talents. Votre vision. Notre intelligence.</h2><p>Pilotez vos recrutements et transformez chaque CV en un parcours professionnel intelligible et exploitable.</p><button class="btn" data-action="go:/candidates/import">${ico('upload')} Importer de nouveaux CV</button></div><div class="hero-art"><div class="float a">${ico('brain')}</div><div class="float b">${ico('users')}</div><div class="float c">${ico('chart')}</div><div class="float d">${ico('spark')}</div></div></div>
<div class="grid grid-4">${stats.map(([l,v,ic,cls,foot])=>`<div class="card kpi"><div class="kpi-head"><div class="kpi-icon ${cls}">${ico(ic)}</div><span class="badge gray">Démo</span></div><div class="kpi-value">${num(v)}</div><div class="kpi-label">${l}</div><div class="kpi-foot ${cls==='amber'?'neutral':''}">${foot}</div></div>`).join('')}</div>
<section class="card card-pad mt"><div class="card-head"><div><h2>Tendances & performance</h2><p>Profils à l’écoute du marché, métiers demandés et activité de l’équipe</p></div><span class="badge green">Détail intégré au tableau de bord</span></div><div class="grid grid-4"><div class="mk-mini-metric"><small>Profils à l’écoute</small><strong>${db.candidates.filter(c=>['À l’écoute','Actif'].includes(c.mobilityStatus)).length}</strong></div><div class="mk-mini-metric"><small>Métiers demandés</small><strong>${new Set(db.jobs.map(j=>j.title)).size}</strong></div><div class="mk-mini-metric"><small>Candidats rapprochés</small><strong>${db.pipeline.length}</strong></div><div class="mk-mini-metric"><small>Taux d’objectif</small><strong>${Math.round(db.pipeline.filter(p=>p.stage==='Recruté').length/Math.max(1,db.pipeline.length)*100)}%</strong></div></div><div class="grid grid-2 mt"><div><div class="mk-subtle">Évolution des candidatures · 8 derniers mois</div><div class="bar-chart">${[18,24,21,32,29,41,38,47].map((v,i)=>`<div class="bar-col"><div class="bar-value" title="${v} candidatures" style="height:${v*2}px"></div><small>${['Avr','Mai','Juin','Juil','Aoû','Sep','Oct','Nov'][i]}</small></div>`).join('')}</div><h3 style="margin-top:22px">Métiers les plus demandés</h3>${[...new Set(db.jobs.map(j=>j.title))].slice(0,6).map((r,i)=>`<div class="mk-barline"><span>${E(r)}</span><div class="progress-track"><div class="progress-fill" style="width:${92-i*12}%"></div></div><strong>${Math.max(1,4-i)}</strong></div>`).join('')}</div><div><div class="mk-subtle">Taux de réalisation par collaborateur</div>${['Yasmine','Omar','Sara','Mehdi'].map((n,i)=>{const done=i+2,goal=5+i;return `<div class="mk-barline"><span>${n}</span><div class="progress-track"><div class="progress-fill" style="width:${done/goal*100}%"></div></div><strong>${Math.round(done/goal*100)}%</strong></div>`}).join('')}</div></div><div class="mt">${cardHead('Performance détaillée par collaborateur','Recrutements, clients, prospects, candidats rapprochés et objectifs')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Collaborateur</th><th>Recrutements</th><th>Clients</th><th>Prospects</th><th>Candidats rapprochés</th><th>Objectif</th><th>Réalisation</th></tr></thead><tbody>${['Yasmine','Omar','Sara','Mehdi'].map((n,i)=>{const done=i+2,goal=5+i;return `<tr><td><strong>${n}</strong></td><td>${done}</td><td>${db.companies.filter(c=>c.id%4===i+1).length+2}</td><td>${3+i}</td><td>${db.pipeline.filter(p=>p.id%4===i).length+3}</td><td>${goal}</td><td><strong class="link">${Math.round(done/goal*100)}%</strong></td></tr>`}).join('')}</tbody></table></div></div></section>
<div class="grid col-main mt"><section class="card card-pad">${cardHead('Évolution des candidatures','Flux de candidatures par mois · données de démonstration',`<span class="badge">2026</span>`)}<div class="bar-chart">${[8,12,10,18,16,21,24,29,26,34,28,39].map((v,i)=>`<div class="bar-col"><div class="bar-value" title="${v} candidatures" style="height:${Math.round(v/40*140)}px"></div><small>${['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Aoû','Sep','Oct','Nov','Déc'][i]}</small></div>`).join('')}</div><div style="height:23px"></div></section><section class="card card-pad">${cardHead('Actions rapides','Accédez directement aux fonctionnalités clés')}<div class="grid grid-2" style="gap:10px">${[['upload','Importer des CV','/candidates/import'],['brain','Matching IA','/matching'],['briefcase','Créer une offre','/jobs/new'],['search','Recherche avancée','/search']].map(([ic,t,r])=>`<a href="#${r}" class="card" style="padding:17px;border-radius:12px;box-shadow:none;display:flex;align-items:center;gap:10px;font-weight:800;font-size:11px;color:#465b71">${ico(ic)}<span>${t}</span>${ico('chevron')}</a>`).join('')}</div><div class="notice" style="margin-top:16px">${ico('spark')} <span><b>Module vedette :</b> explorez le séquenceur interactif pour visualiser les carrières. <a class="link" href="#/candidates/1/journey">Voir la démo</a></span></div></section></div>
<div class="grid col-main mt"><section class="card card-pad">${cardHead('Candidats récemment ajoutés','Derniers dossiers dans la CVthèque',`<a class="link" href="#/candidates">Voir tous ${ico('arrow-right')}</a>`)}${db.candidates.slice(-5).reverse().map(c=>`<div class="list-row">${avatar(c)}<div class="grow"><strong>${E(c.name)}</strong><small>${E(c.role)} · ${E(c.city)}</small></div>${badgeStatus(c.status)}<button class="icon-btn" data-action="go:/candidates/${c.id}" title="Ouvrir le profil">${ico('arrow-right')}</button></div>`).join('')}</section><section class="card card-pad">${cardHead('Offres à pourvoir','Postes ouverts actuellement',`<a class="link" href="#/jobs">Toutes les offres ${ico('arrow-right')}</a>`)}${db.jobs.filter(j=>j.status==='Active').slice(0,5).map(j=>`<div class="list-row"><div class="kpi-icon" style="width:36px;height:36px">${ico('briefcase')}</div><div class="grow"><strong>${E(j.title)}</strong><small>${E(j.city)} · ${j.contract}</small></div><button class="icon-btn" data-action="go:/jobs/${j.id}">${ico('chevron')}</button></div>`).join('')}</section></div>`}
function mkProductModules(){return `<section class="card card-pad mt">${cardHead('L’écosystème MKLEAN','Accès rapide aux modules de la plateforme de recrutement et d’intelligence économique')}<div class="mk-module-grid">${[['briefcase','CRM employeurs','/employers'],['chart','Observatoire emploi','/observatory'],['file','Générateur d’études','/studies'],['layers','Secteurs HCP / CCIS','/sectors'],['calendar','Entretiens & salaires','/interviews'],['calendar','Guides d’entretien','/guides'],['chart','Tendances & performance','/insights'],['brain','Tests psychométriques','/assessments'],['clock','Candidats passifs','/passive'],['globe','Veille emploi','/watch'],['spark','Copilote IA','/copilot']].map(([ic,name,path])=>`<a href="#${path}" class="mk-module-tile">${ico(ic)}<strong>${E(name)}</strong>${ico('arrow-right')}</a>`).join('')}</div></section>`}
function candidatesFiltered(){return db.candidates.filter(c=>(!ui.query||norm(`${c.name} ${c.role} ${c.skills.join(' ')}`).includes(norm(ui.query)))&&(!ui.city||c.city===ui.city)&&(!ui.status||c.status===ui.status))}
function insightsPage(){const listening=db.candidates.filter(c=>['À l’écoute','Actif'].includes(c.mobilityStatus));const months=[18,24,21,32,29,41,38,47];const roles=[...new Set(db.jobs.map(j=>j.title))].slice(0,6);return heading('PILOTAGE / INTELLIGENCE MARCHÉ','Tendances & performance','Suivez les profils à l’écoute du marché, les métiers demandés et l’activité de l’équipe.',btn(`${ico('download')} Exporter le rapport`,'export-insights',true))+`<div class="grid grid-4">${miniKpi('Profils à l’écoute',listening.length,'users','Statut et date de profil')}${miniKpi('Métiers demandés',roles.length,'briefcase','Offres actives')}${miniKpi('Candidats rapprochés',db.pipeline.length,'brain','Matchings enregistrés')}${miniKpi('Taux d’objectif',Math.round(db.pipeline.filter(p=>p.stage==='Recruté').length/Math.max(1,db.pipeline.length)*100)+'%','target','Réalisé ce mois')}</div><div class="grid grid-2 mt"><section class="card card-pad">${cardHead('Évolution des candidatures','Volume mensuel et profils à l’écoute') }<div class="bar-chart">${months.map((v,i)=>`<div class="bar-col"><div class="bar-value" title="${v} candidatures" style="height:${v*3}px"></div><small>${['Avr','Mai','Juin','Juil','Aoû','Sep','Oct','Nov'][i]}</small></div>`).join('')}</div><div class="notice mt">${ico('info')} Les signaux LinkedIn sont utilisés uniquement lorsqu’ils sont accessibles et autorisés ; aucune collecte automatique n’est activée.</div></section><section class="card card-pad">${cardHead('Métiers les plus demandés','Répartition des offres actives')}${roles.map((r,i)=>`<div class="mk-barline"><span>${E(r)}</span><div class="progress-track"><div class="progress-fill" style="width:${92-i*12}%"></div></div><strong>${Math.max(1,4-i)}</strong></div>`).join('')}</section></div><div class="card card-pad mt">${cardHead('Performance par collaborateur','Recrutements, clients, prospects, rapprochements et objectifs')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Collaborateur</th><th>Recrutements</th><th>Clients & prospects</th><th>Rapprochements</th><th>Objectif</th><th>Réalisation</th></tr></thead><tbody>${['Yasmine','Omar','Sara','Mehdi'].map((n,i)=>{const done=i+2,goal=5+i;return `<tr><td><strong>${n}</strong></td><td>${done}</td><td>${db.companies.filter(c=>c.id%4===i+1).length+2} / ${3+i}</td><td>${db.pipeline.filter(p=>p.id%4===i).length+3}</td><td>${goal}</td><td><strong class="link">${Math.round(done/goal*100)}%</strong></td></tr>`}).join('')}</tbody></table></div></div>`}

function guidesPage(){return heading('RECRUTEMENT / ENTRETIENS','Guides d’entretien','Créez des trames personnalisables par poste et entreprise pour structurer les évaluations.',btn(`${ico('plus')} Nouveau guide`,'new-guide',true))+`<div class="grid grid-2">${db.interviewGuides.map(g=>`<section class="card card-pad"><div class="flex" style="justify-content:space-between"><div><div class="eyebrow">${E(g.company)}</div><h2>${E(g.name)}</h2><p class="muted">${E(g.role)} · ${g.questions.length} questions</p></div>${chip(g.active?'Actif':'Brouillon',g.active?'green':'orange')}</div><ol class="guide-list">${g.questions.map(q=>`<li>${E(q)}</li>`).join('')}</ol><button class="btn btn-sm" data-action="guide-use:${g.id}">${ico('calendar')} Utiliser en entretien</button></section>`).join('')}</div><div class="notice mt">${ico('spark')} Suggestions intelligentes : les guides peuvent être adaptés à partir des compétences de l’offre et du contexte de l’entreprise.</div>`}
function companyEvaluationPage(id){const co=cs(id);if(!co)return `<div class="card card-pad">Entreprise introuvable.</div>`;const rows=db.companyEvaluations.filter(x=>x.companyId===id);return heading('ENTREPRISE / ÉVALUATION','Évaluation des candidats',`${co.name} · retours employeur et suivi de stabilité`,btn(`${ico('arrow-left')} Fiche entreprise`,'go:/employers/'+id))+`<div class="grid grid-2"><section class="card card-pad">${cardHead('Nouvelle évaluation','Feedback après présentation ou recrutement')}<form id="company-evaluation-form"><input type="hidden" name="companyId" value="${id}"><div class="field"><label>Candidat</label><select class="select" name="candidateId">${db.candidates.map(c=>`<option value="${c.id}">${E(c.name)} · ${E(c.role)}</option>`).join('')}</select></div><div class="grid grid-2"><div class="field"><label>Note / 5</label><input class="input" type="number" name="rating" min="1" max="5" value="4"></div><div class="field"><label>Stabilité</label><select class="select" name="stability"><option>En poste</option><option>À surveiller</option><option>Sortie</option></select></div></div><div class="field"><label>Commentaire</label><textarea class="textarea" name="comment" required placeholder="Retour de l’employeur"></textarea></div><button class="btn btn-primary" type="submit">${ico('check')} Enregistrer</button></form></section><section class="card card-pad">${cardHead('Historique des évaluations','Suivi post-recrutement')} ${rows.map(x=>`<div class="list-row"><div class="grow"><strong>${E(getC(x.candidateId)?.name||'Candidat')}</strong><small>${E(x.date)} · Stabilité : ${E(x.stability)}</small><p class="mk-subtle">${E(x.comment)}</p></div>${chip(x.rating+'/5','green')}</div>`).join('')||none('Aucun retour employeur.')}</section></div>`}

function candidatesPage(){const arr=candidatesFiltered();return heading('CVTHÈQUE / TALENTS','Gestion des candidats','Centralisez, recherchez et analysez tous les profils professionnels.',`${btn(`${ico('upload')} Importer des CV`,'go:/candidates/import')}${btn(`${ico('plus')} Ajouter un candidat`,'new-candidate',true)}`)+`<div class="card card-pad"><div class="toolbar"><label class="searchfield">${ico('search')}<input id="candidate-filter" value="${E(ui.query)}" placeholder="Nom, métier, compétence..."></label><select class="select" id="city-filter"><option value="">Toutes les villes</option>${cities.map(c=>`<option ${ui.city===c?'selected':''}>${c}</option>`).join('')}</select><select class="select" id="status-filter"><option value="">Tous les statuts</option>${['Validé','À vérifier','En cours'].map(x=>`<option ${ui.status===x?'selected':''}>${x}</option>`).join('')}</select><div class="toggle-group"><button class="${ui.view==='table'?'active':''}" data-action="cview:table">${ico('list')}</button><button class="${ui.view==='cards'?'active':''}" data-action="cview:cards">${ico('grid')}</button></div></div><div style="color:#8595a5;font-size:11px;margin-bottom:14px">${arr.length} candidat(s) trouvé(s) · Étiquettes automatiques activées</div><div id="candidate-results">${candidateResults(arr)}</div></div>`}
function candidateResults(arr){if(!arr.length)return `<div class="empty">${ico('search')}<h3>Aucun candidat trouvé</h3><p>Modifiez vos critères de recherche.</p></div>`;
if(ui.view==='cards')return `<div class="grid grid-3">${arr.map(c=>`<div class="card" style="padding:18px;box-shadow:none"><div class="flex">${avatar(c,45)}<div style="min-width:0"><strong style="font-size:12px">${E(c.name)}</strong><small style="display:block;margin-top:4px">${E(c.city)} · ${c.experience} ans d'exp.</small></div></div><h3 style="margin:14px 0 12px;min-height:36px">${E(c.role)}</h3>${skilltags(c.skills,3)}<div style="display:flex;justify-content:space-between;align-items:center;margin-top:17px">${badgeStatus(c.status)}<button class="btn btn-sm" data-action="go:/candidates/${c.id}">Voir le profil ${ico('arrow-right')}</button></div></div>`).join('')}</div>`;
return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Candidat</th><th>Spécialité</th><th>Expérience</th><th>Compétences</th><th>Ville</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${arr.map(c=>`<tr><td><div class="flex">${avatar(c,34)}<div><div class="candidate-name">${E(c.name)}</div><small>${E(c.education)}</small></div></div></td><td>${E(c.role)}</td><td>${c.experience} ans</td><td>${skilltags(c.skills,2)}</td><td>${E(c.city)}</td><td>${badgeStatus(c.status)}</td><td><div class="flex" style="gap:4px"><button class="icon-btn" title="Fiche candidat" data-action="go:/candidates/${c.id}">${ico('eye')}</button><button class="icon-btn" title="Séquenceur" data-action="go:/candidates/${c.id}/journey">${ico('timeline')}</button><button class="icon-btn" title="Matching" data-action="match-candidate:${c.id}">${ico('brain')}</button></div></td></tr>`).join('')}</tbody></table></div>`}
function candidateSuggestions(c){
 const jobs=db.jobs.map(j=>({j,...match(c,j)})).filter(x=>x.j.status==='Active').sort((a,b)=>b.score-a.score).slice(0,4);
 const companies=[];jobs.forEach(({j,score,found})=>{const name=j.company||'Entreprise non renseignée';const current=companies.find(x=>x.name===name);if(current){current.score=Math.max(current.score,score);current.jobs++;current.found=[...new Set([...current.found,...found])]}else companies.push({name,score,jobs:1,found})});
 return `<section class="card card-pad mk-recommendations mt"><div class="card-head"><div><h2>Suggestions intelligentes</h2><p>Postes et entreprises rapprochés de votre profil</p></div>${pill('Profil analysé','green')}</div><div class="grid grid-2"><div><h3 class="mk-reco-title">Postes recommandés</h3>${jobs.map(({j,score,found})=>`<div class="mk-reco-item"><div class="mk-reco-icon">${ico('briefcase')}</div><div class="grow"><strong>${E(j.title)}</strong><small>${E(j.company||'Entreprise non renseignée')} · ${E(j.city)} · ${j.contract}</small><div class="tags" style="margin-top:7px">${skilltags(found,3)}</div></div><span class="badge green">${score}%</span><button class="icon-btn" title="Voir l'offre" data-action="job-preview:${j.id}">${ico('chevron')}</button></div>`).join('')||none('Aucun poste actif correspondant.')}</div><div><h3 class="mk-reco-title">Entreprises à découvrir</h3>${companies.map(x=>`<div class="mk-reco-item"><div class="mk-reco-icon company">${ico('building')}</div><div class="grow"><strong>${E(x.name)}</strong><small>${x.jobs} poste(s) compatible(s) · ${x.found.length} compétence(s) en commun</small></div><span class="badge">${x.score}%</span></div>`).join('')||none('Aucune entreprise recommandée.')}</div></div><div class="notice mt">${ico('spark')} <span>Les scores sont indicatifs et combinent les compétences et l'expérience. Vérifiez chaque offre avant de candidater.</span></div></section>`;
}
function candidateOverview(c){return `<div class="grid col-main"><section class="card card-pad">${cardHead('Profil professionnel','Synthèse des informations extraites du CV')}<p style="font-size:12px;color:#60758a;line-height:1.8">${E(c.bio)}</p><h3 style="margin-top:22px;margin-bottom:13px">Compétences principales</h3>${skilltags(c.skills,10)}<h3 style="margin-top:24px;margin-bottom:7px">Parcours récent</h3>${c.journey.filter(x=>x.type==='job').slice().reverse().map(x=>`<div class="list-row"><div class="kpi-icon">${ico('briefcase')}</div><div class="grow"><strong>${E(x.title)}</strong><small>${E(x.org)} · ${x.start}–${x.end}</small></div></div>`).join('')}<div style="margin-top:18px">${btn(`${ico('timeline')} Explorer le parcours complet`,`go:/candidates/${c.id}/journey`,true)}</div></section><aside class="card card-pad">${cardHead('Informations du candidat')}${[['Adresse email',c.email],['Téléphone',c.phone],['Localisation',c.city],['Expérience',`${c.experience} ans`],['Formation',c.education],['Source',c.source],['Dernier import',fmtDate(c.imported)]].map(([l,v])=>`<div class="info-pair"><span>${E(l)}</span><strong>${E(v)}</strong></div>`).join('')}<div class="notice warn" style="margin-top:21px">${ico('info')} Données de démonstration : les coordonnées et expériences sont fictives.</div></aside></div>`}
function candidatePage(id){const c=getC(id);if(!c)return `<div class="card card-pad">Candidat introuvable.</div>`;
const tabs=[['overview','Vue générale & suggestions intelligentes'],['career','Parcours · formation · compétences'],['docs','Documents & références'],['evaluation','Entretiens & évaluations'],['recruitment','Recrutement & placements']];
let body='';if(ui.profileTab==='overview')body=candidateOverview(c)+candidateSuggestions(c);
else if(ui.profileTab==='docs')body=candidateDocumentsReferencesWithHistory(c);
else if(ui.profileTab==='suggestions')body=candidateSuggestions(c);
else if(ui.profileTab==='career')body=`<div class="grid grid-2"><section class="card card-pad">${cardHead('Expériences professionnelles','Parcours issu du CV · validation humaine')}<div class="timeline">${c.journey.filter(x=>x.type==='job').map(eventCard).join('')}</div></section><section class="card card-pad">${cardHead('Formations & compétences','Diplômes, certifications et savoir-faire associés')}<div class="timeline">${c.journey.filter(x=>x.type!=='job').map(eventCard).join('')}</div><h3 style="margin-top:22px">Compétences principales</h3>${skilltags(c.skills,20)}</section></div>`;
else if(ui.profileTab==='evaluation')body=`<div class="grid grid-2"><section class="card card-pad">${cardHead('Entretiens','Qualification et échanges enregistrés')}${db.interviews.filter(i=>i.candidateId===c.id).map(i=>`<div class="list-row"><div class="grow"><strong>${E(i.type)} · ${E(i.date)}</strong><small>Prétentions ${money(i.expectedMin)} – ${money(i.expectedMax)} · ${E(i.mobility||'—')}</small></div>${btn('Voir','mk:interview-details:'+i.id)}</div>`).join('')||none('Aucun entretien saisi.')}</section><section class="card card-pad">${cardHead('Évaluations','Résultats soumis à validation humaine')}${db.assessments.filter(x=>x.candidateId===c.id).map(x=>`<div class="list-row"><div class="grow"><strong>${E(x.type)}</strong><small>${E(x.date)} · ${E(x.status)}</small></div>${chip(x.result||'À compléter')}</div>`).join('')||none('Aucune évaluation assignée.')}</section></div>`;
else if(ui.profileTab==='recruitment')body=`<div class="grid grid-2"><section class="card card-pad">${cardHead('Candidatures & matching','Offres liées et prochaines étapes')}${db.pipeline.filter(p=>p.candidateId===c.id).map(p=>`<div class="list-row"><div class="grow"><strong>${E(getJ(p.jobId)?.title||'Offre')}</strong><small>${E(getJ(p.jobId)?.company||'Entreprise')} · ${E(p.stage)}</small></div>${btn('Voir','go:/jobs/'+p.jobId)}</div>`).join('')||none('Aucune candidature affectée.')}${btn('Classement des profils','go:/ranking')}</section><section class="card card-pad">${cardHead('Placements','Suivi post-recrutement consenti')}${db.placements.filter(x=>x.candidateId===c.id).map(x=>`<div class="list-row"><div class="grow"><strong>${E(cs(x.companyId)?.name||'Entreprise')}</strong><small>${E(x.status)} · Prochain point ${E(x.followup||'—')}</small></div></div>`).join('')||none('Aucun placement associé.')}${btn('Voir tous les placements','go:/placements')}</section></div>`;
else if(ui.profileTab==='experiences'||ui.profileTab==='education') {const type=ui.profileTab==='experiences'?'job':'education';body=`<div class="card card-pad">${cardHead(type==='job'?'Expériences professionnelles':'Parcours académique','Informations issues du CV · validation humaine')}<div class="timeline">${c.journey.filter(x=>x.type===type).map(x=>eventCard(x)).join('')}</div></div>`}
else if(ui.profileTab==='skills') body=`<div class="grid col-main"><div class="card card-pad">${cardHead('Référentiel de compétences','Compétences mentionnées dans le profil')}${c.skills.map((s,i)=>`<div class="skill-progress"><span>${E(s)}</span><div class="progress-track"><div class="progress-fill" style="width:${95-i*12}%"></div></div><b style="font-size:10px;color:#8595a5">Déclarée</b></div>`).join('')}<div class="notice mt">${ico('info')} Les barres illustrent la complétude de l'information, pas un niveau de maîtrise validé.</div></div><div class="card card-pad">${cardHead('Compétences par expérience','Traçabilité et contexte')}${c.journey.filter(x=>x.type==='job').map(x=>`<div class="list-row"><div class="grow"><strong>${E(x.title)}</strong><small>${x.start}–${x.end}</small><div style="margin-top:9px">${skilltags(x.skills,6)}</div></div></div>`).join('')}</div></div>`;
else if(ui.profileTab==='documents')body=`<div class="card card-pad">${cardHead('Documents associés','Gérez votre CV et téléchargez le format MKLEAN')}<div class="source-card"><div class="source-icon">${ico('file')}</div><div class="grow"><h3>CV_${E(c.name.replaceAll(' ','_'))}.pdf</h3><p>Source : ${E(c.source)} · Dernier traitement : ${fmtDate(c.imported)}</p>${pill('Profil structuré','green')}</div><button class="btn btn-sm" data-action="cv-info">${ico('eye')} Aperçu</button></div><div class="mk-cv-download"><div class="mk-reco-icon">${ico('download')}</div><div class="grow"><strong>CV standardisé MKLEAN</strong><small>Structure claire, compétences, expériences et formation regroupées pour faciliter la lecture par les recruteurs.</small></div><button class="btn btn-primary" data-action="download-mklean-cv:${c.id}">${ico('download')} Télécharger le CV</button></div><div class="notice mt">${ico('info')} Le document est généré à partir des informations présentes dans votre espace candidat. Vérifiez-les avant téléchargement.</div></div>`;
else if(ui.profileTab==='references'){body=`<div class="grid grid-2"><section class="card card-pad">${cardHead('Prise de références','Centralisez les retours des anciens employeurs et les appels téléphoniques')}${c.references.map(r=>`<div class="list-row"><div class="kpi-icon">${ico('phone')}</div><div class="grow"><strong>${E(r.name)} · ${E(r.company)}</strong><small>${E(r.date)} · ${E(r.relationship)}</small><p class="mk-subtle">${E(r.comment)}</p></div>${chip(r.rating+'/5','green')}</div>`).join('')||none('Aucune référence enregistrée.')}</section><section class="card card-pad"><form id="reference-form"><input type="hidden" name="candidateId" value="${c.id}"><div class="field"><label>Ancien employeur / contact *</label><input class="input" name="name" required placeholder="Nom du référent"></div><div class="field"><label>Entreprise</label><input class="input" name="company" placeholder="Entreprise précédente"></div><div class="field"><label>Commentaire</label><textarea class="textarea" name="comment" placeholder="Synthèse de l'appel téléphonique"></textarea></div><div class="grid grid-2"><input class="input" name="relationship" placeholder="Relation"><input class="input" name="rating" type="number" min="1" max="5" value="4"></div><button class="btn btn-primary mt" type="submit">${ico('check')} Enregistrer la référence</button></form><div class="notice mt">${ico('phone')} Transcription vocale : le champ de synthèse est prêt à recevoir une transcription lorsqu’un fournisseur audio autorisé sera connecté.</div></section></div>`}
else if(ui.profileTab==='report'){body=`<section class="card card-pad mk-paper">${cardHead('Rapport final candidat','Synthèse du parcours, tests, références et processus de recrutement',btn(`${ico('download')} Télécharger`, 'download-candidate-report:'+c.id, true))}<div class="mk-paper-brand">MKLEAN<span>TALENT AI · RAPPORT CANDIDAT</span></div><div class="mk-report-separator"></div><h1>${E(c.name)}</h1><p>${E(c.role)} · ${E(c.city)} · ${c.experience} ans d’expérience</p><div class="grid grid-3 mt">${[['Tests',db.assessments.filter(x=>x.candidateId===c.id).length],['Références',c.references.length],['Étapes recrutement',db.pipeline.filter(x=>x.candidateId===c.id).length]].map(([l,v])=>`<div class="mk-mini-metric"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><h2>Conclusion de recrutement</h2><p>Profil structuré à partir des informations déclarées, des évaluations disponibles et des échanges enregistrés. Cette synthèse reste soumise à la validation humaine.</p><h2>Compétences clés</h2><div class="mk-report-list">${c.skills.map(s=>`• ${E(s)}`).join('<br>')}</div><div class="notice warn mt">${ico('shield')} Rapport de démonstration : aucune décision automatisée et aucune donnée audio réelle n’est stockée.</div></section>`}
else if(ui.profileTab==='matching'){const best=db.jobs.map(j=>({j,...match(c,j)})).sort((a,b)=>b.score-a.score).slice(0,6);body=`<div class="card card-pad">${cardHead('Offres correspondant au profil','Scores indicatifs basés sur les compétences et l’expérience')}${best.map(({j,score,found,missing})=>{const assigned=db.pipeline.some(p=>p.candidateId===c.id&&p.jobId===j.id);return `<div class="match-row"><div class="score-circle" style="--pct:${score}%"><span>${score}%</span></div><div class="grow"><strong>${E(j.title)}</strong><p>${E(j.company||'Entreprise non renseignée')} · ${E(j.city)} · ${found.length} compétence(s) retrouvée(s) · ${missing.length} écart(s)</p>${skilltags(found,3)}</div><button class="btn btn-sm" data-action="job-preview:${j.id}">${ico('eye')} Voir l'offre</button><button class="btn btn-sm ${assigned?'btn-success':''}" data-action="assign-job:${c.id}:${j.id}">${ico(assigned?'check':'plus')} ${assigned?'Affectée':'Affecter'}</button></div>`}).join('')}</div>`}
else if(ui.profileTab==='interviews')body=`<section class="card card-pad">${cardHead('Qualification & entretiens','Rémunération, mobilité, attentes et motifs déclarés')}${db.interviews.filter(i=>i.candidateId===c.id).map(i=>`<div class="list-row"><div class="grow"><strong>${E(i.type)} · ${E(i.date)}</strong><small>Prétentions ${money(i.expectedMin)} – ${money(i.expectedMax)} · ${E(i.mobility)}</small></div>${btn('Voir','mk:interview-details:'+i.id)}</div>`).join('')||none('Aucun entretien saisi.')}${btn('Tous les entretiens','go:/interviews')}</section>`;
else if(ui.profileTab==='assessments'){const reports=db.assessments.filter(x=>x.candidateId===c.id);body=`<div class="notice warn mb">${ico('shield')} <span>Résultats de démonstration uniquement. Les radars illustrent des dimensions de test et ne constituent ni un diagnostic, ni un score normé, ni une décision automatique.</span></div><div class="grid grid-2">${reports.map(x=>assessmentReport(x,c)).join('')||`<section class="card card-pad">${none('Aucune évaluation assignée.')}${btn('Planifier une évaluation','go:/assessments',true)}</section>`}</div>`;}
else if(ui.profileTab==='placements')body=`<section class="card card-pad">${cardHead('Suivi post-recrutement','Uniquement avec consentement et finalité définie')}${db.placements.filter(x=>x.candidateId===c.id).map(x=>`<div class="list-row"><div class="grow"><strong>${E(cs(x.companyId)?.name||'Entreprise')}</strong><small>${E(x.status)} · Prochain point ${E(x.followup)}</small></div></div>`).join('')||none('Aucun placement associé.')}${btn('Voir les placements','go:/placements')}</section>`;
else if(ui.profileTab==='communications')body=communicationPanel(c);
else body=`<div class="card card-pad">${cardHead('Historique des actions','Traçabilité du dossier')}<div class="list-row"><div class="kpi-icon">${ico('upload')}</div><div class="grow"><strong>Import du CV</strong><small>${fmtDate(c.imported)} · Extraction simulée</small></div></div><div class="list-row"><div class="kpi-icon">${ico('shield')}</div><div class="grow"><strong>${c.validated?'Profil vérifié':'Profil en attente de vérification'}</strong><small>Validation humaine des données</small></div></div>${db.pipeline.filter(p=>p.candidateId===c.id).map(p=>`<div class="list-row"><div class="kpi-icon">${ico('briefcase')}</div><div class="grow"><strong>Étape recrutement : ${E(p.stage)}</strong><small>${E(getJ(p.jobId)?.title||'Offre')}</small></div></div>`).join('')}</div>`;
return heading('CANDIDATS / DOSSIER',c.name,`${c.role} · ${c.city}`,`${btn(`${ico('arrow-left')} Retour CVthèque`,'go:/candidates')}${btn(`${ico('edit')} Modifier`,'edit-candidate:'+id)}${btn(`${ico('timeline')} Séquenceur`,'go:/candidates/'+id+'/journey',true)}`)+`<div class="card candidate-hero mb">${avatar(c)}<div style="flex:1"><div class="flex" style="flex-wrap:wrap"><h2 style="margin:0">${E(c.name)}</h2>${badgeStatus(c.status)}</div><p style="margin-top:6px">${E(c.role)}</p><div class="meta-line"><span>${ico('map')}${E(c.city)}</span><span>${ico('briefcase')}${c.experience} ans d'expérience</span><span>${ico('graduation')}${E(c.education)}</span></div></div><button class="btn" data-action="go:/candidates/${c.id}/enrichment">${ico('globe')} Enrichir le profil</button><button class="btn" data-action="go:/communications/timeline">${ico('timeline')} Interactions</button><button class="btn btn-primary" data-action="download-mklean-cv:${c.id}">${ico('download')} Télécharger le CV MKLEAN</button><button class="btn btn-dark" data-action="candidate-report:${c.id}">${ico('file')} Rapport final PDF</button><button class="btn" data-action="match-candidate:${c.id}">${ico('brain')} Matching IA</button></div><div class="subtabs">${tabs.map(([k,l])=>`<button class="subtab ${ui.profileTab===k?'active':''}" data-action="profile-tab:${k}">${l}</button>`).join('')}</div>${body}`;}
function eventCard(x){return `<article class="timeline-event ${E(x.type)}" data-action="event:${E(x.id)}"><div class="flex" style="justify-content:space-between;flex-wrap:wrap"><span class="year">${x.start}${x.end!==x.start?' — '+x.end:''}</span>${pill(x.type==='education'?'Formation':x.type==='certification'?'Certification':'Expérience',x.type==='education'?'purple':x.type==='certification'?'green':'')}</div><h3>${E(x.title)}</h3><p>${E(x.org)}</p>${skilltags(x.skills,3)}<div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px"><small>${E(x.source||'CV')} · ${x.verified?'Vérifiée':'À confirmer'}</small><span class="link" style="font-size:11px">Détails ${ico('chevron')}</span></div></article>`}
function journeyPage(id){const c=getC(id);if(!c)return '<div class="card card-pad">Profil introuvable.</div>';const events=c.journey.filter(x=>ui.journeyType==='all'||x.type===ui.journeyType);return heading('INNOVATION / SÉQUENCEUR','Parcours professionnel',`Exploration chronologique du parcours de ${c.name}.`,`${btn(`${ico('arrow-left')} Fiche candidat`,'go:/candidates/'+c.id)}${btn(`${ico('edit')} Modifier le parcours`,'edit-journey:'+id)}${btn(`${ico('download')} Exporter la vue`,'export-journey',true)}`)+`<div class="card candidate-hero mb">${avatar(c,54)}<div style="flex:1"><h2 style="margin:0 0 3px">${E(c.name)}</h2><p>${E(c.role)} · ${c.experience} ans d'expérience</p></div>${pill(`${c.journey.length} événements`,'green')}</div><div class="grid col-main"><div><div class="card card-pad">${cardHead('Séquenceur visuel','Explorez les étapes et leur provenance')}<div class="toolbar" style="justify-content:space-between"><div class="toggle-group"><button class="${ui.journeyMode==='horizontal'?'active':''}" data-action="journey-mode:horizontal">Horizontale</button><button class="${ui.journeyMode==='vertical'?'active':''}" data-action="journey-mode:vertical">Verticale</button></div><select class="select" id="journey-filter"><option value="all">Tous les événements</option><option value="job" ${ui.journeyType==='job'?'selected':''}>Expériences</option><option value="education" ${ui.journeyType==='education'?'selected':''}>Formations</option><option value="certification" ${ui.journeyType==='certification'?'selected':''}>Certifications</option></select><button class="btn btn-sm" data-action="journey-zoom">${ico('search')} ${ui.journeyZoom?'Réduire':'Zoomer'}</button></div><div class="timeline ${ui.journeyMode==='horizontal'?'horizontal':''} ${ui.journeyZoom?'zoomed':''}">${events.map(eventCard).join('')||'<div class="empty">Aucun événement dans cette catégorie.</div>'}</div><div class="notice" style="margin-top:13px">${ico('info')} Cliquez sur une étape pour consulter la description, les compétences associées et la source des données.</div></div><div class="card card-pad mt">${cardHead('Évolution des compétences','Compétences associées à chaque période')}${c.journey.filter(x=>x.type==='job').map(x=>`<div class="list-row"><div style="min-width:75px;color:#0e84c6;font-size:10px;font-weight:800">${x.start}–${x.end}</div><div class="grow"><strong>${E(x.title)}</strong><div style="margin-top:8px">${skilltags(x.skills,8)}</div></div></div>`).join('')}</div></div><aside><div class="card card-pad">${cardHead('Synthèse du parcours','Données reconstituées à partir du CV')}<div class="journey-summary"><div class="mini-stat"><strong>${c.experience}</strong><span>Années d'exp.</span></div><div class="mini-stat"><strong>${c.journey.filter(x=>x.type==='job').length}</strong><span>Postes</span></div><div class="mini-stat"><strong>${c.journey.length}</strong><span>Étapes</span></div></div><h3 style="margin-top:23px">Compétences identifiées</h3>${skilltags(c.skills,8)}<h3 style="margin-top:23px">Légende</h3>${[['#1389d6','Expériences'],['#9b7cdd','Formations'],['#14ad93','Certifications']].map(([color,text])=>`<div class="legend"><span><i style="background:${color}"></i>${text}</span></div>`).join('')}</div><div class="card card-pad mt">${cardHead('Fiabilité et provenance')}${[['CV importé',c.journey.filter(x=>x.source==='CV').length],['Événements confirmés',c.journey.filter(x=>x.verified).length],['À vérifier',c.journey.filter(x=>!x.verified).length]].map(([l,v])=>`<div class="info-pair"><span>${l}</span><strong>${v}</strong></div>`).join('')}<div style="margin-top:17px">${btn(`${ico('globe')} Enrichissement web`,'go:/candidates/'+id+'/enrichment',false,'btn-block')}</div></div></aside></div>`}
function importPage(){const step=ui.importStep;const steps=['Documents','Analyse IA','Vérification','Enregistrement'];let inner='';
if(step===1)inner=`<div class="upload-zone" id="drop-zone" data-action="choose-files">${ico('upload')}<h3>Glissez vos fichiers ici</h3><p>Ou sélectionnez des CV PDF / Word depuis votre ordinateur.</p><button class="btn btn-primary" type="button" data-action="choose-files">${ico('plus')} Choisir des documents</button><input type="file" style="display:none" id="cv-files" multiple accept=".pdf,.doc,.docx"></div>${ui.importFiles.length?`<div class="card mt" style="padding:15px">${ui.importFiles.map(f=>`<div class="list-row">${ico('file')}<div class="grow"><strong>${E(f)}</strong><small>Document sélectionné · traitement simulé</small></div>${pill('Prêt','green')}</div>`).join('')}</div>`:''}<div class="notice mt">${ico('info')} Prototype sans OCR ni IA connectés : le traitement sera simulé avec un profil fictif, sans lecture effective du contenu du fichier.</div><div style="text-align:right;margin-top:20px">${btn(`${ico('arrow-right')} Analyser (démo)`,'import-next',true)}</div>`;
else if(step===2)inner=`<div style="text-align:center;padding:24px 0"> <div class="kpi-icon" style="margin:auto;width:64px;height:64px">${ico('brain')}</div><h2 style="margin-top:15px">Analyse documentaire simulée terminée</h2><p class="muted">Les informations ci-dessous sont des exemples préremplis, sans extraction de fichier réel.</p></div><div class="grid grid-3">${[['Identité','Nom et coordonnées','check'],['Parcours','Expériences et diplômes','timeline'],['Compétences','Technologies et savoir-faire','spark']].map(([t,d,ic])=>`<div class="card" style="padding:20px;box-shadow:none">${ico(ic)}<h3 style="margin-top:11px">${t}</h3><small>${d}</small><div style="margin-top:11px">${pill('Démo','green')}</div></div>`).join('')}</div><div style="display:flex;justify-content:space-between;margin-top:22px">${btn('Retour','import-back')}${btn(`Vérifier les données ${ico('arrow-right')}`,'import-next',true)}</div>`;
else if(step===3)inner=`<p class="muted" style="line-height:1.7">Vérifiez et corrigez le profil fictif avant sa création. Ces données seront conservées localement dans votre navigateur.</p><form id="import-review" class="form-grid"><div class="field"><label>Nom complet *</label><input name="name" required class="input" value="${E(ui.importValues.name||'Nour El Mansouri')}"></div><div class="field"><label>Intitulé professionnel *</label><input name="role" required class="input" value="${E(ui.importValues.role||'Ingénieure logiciel')}"></div><div class="field"><label>Ville</label><input name="city" class="input" value="${E(ui.importValues.city||'Marrakech')}"></div><div class="field"><label>Années d'expérience</label><input name="experience" type="number" min="0" max="55" class="input" value="${E(ui.importValues.experience||'4')}"></div><div class="field full"><label>Compétences (séparées par des virgules)</label><input name="skills" class="input" value="${E(ui.importValues.skills||'Python, Django, SQL, Docker')}"></div><div class="field full"><label>Formation</label><input name="education" class="input" value="${E(ui.importValues.education||'Master informatique')}"></div><div class="field full" style="display:flex;flex-direction:row;justify-content:space-between"><button class="btn" type="button" data-action="import-back">${ico('arrow-left')} Retour</button><button class="btn btn-primary" type="submit">Valider le profil ${ico('check')}</button></div></form>`;
else inner=`<div style="text-align:center;padding:28px"><div class="kpi-icon teal" style="width:66px;height:66px;margin:0 auto 17px">${ico('check')}</div><h2>Profil créé avec succès</h2><p class="muted">Le candidat a été ajouté à la CVthèque de démonstration.</p><div class="flex" style="justify-content:center;margin-top:23px">${btn('Importer un autre CV','import-reset')}${btn(`Ouvrir la fiche candidat ${ico('arrow-right')}`,'go:/candidates/'+(ui.lastImported||db.candidates.at(-1).id),true)}</div></div>`;
return heading('CVTHÈQUE / IMPORTATION','Importation intelligente des CV','Assistant d’importation et de structuration des profils.','')+`<div class="card card-pad" style="max-width:930px;margin:0 auto"><div class="stepper">${steps.map((l,i)=>`<div class="step ${step===i+1?'active':step>i+1?'done':''}"><b>${step>i+1?ico('check'):i+1}</b><span>${l}</span></div>`).join('')}</div>${inner}</div>`}
function searchPage(){const q=ui.searchApplied||'';const tokens=norm(q).split(/\W+/).filter(s=>s.length>2 && !['avec','dans','pour','ayant','experience','ans','plus','moins','cherche','profil','candidat','une','des','les','les','ingenieur'].includes(s));const res=q?db.candidates.map(c=>{const matchCount=tokens.filter(t=>norm(`${c.role} ${c.skills.join(' ')} ${c.city} ${c.bio}`).includes(t)).length;const expQ=(q.match(/(\d+)\s*ans/i)||[])[1];const pass=(!expQ||c.experience>=Number(expQ));return {c,score:pass?matchCount:-1}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score):db.candidates.map(c=>({c,score:1})).slice(0,12);
return heading('INTELLIGENCE RH / RECHERCHE','Recherche intelligente','Retrouvez des profils à partir de compétences, de métiers ou d’une requête en langage naturel.',btn(`${ico('filter')} Parcourir la CVthèque`,'go:/candidates'))+`<div class="card card-pad" style="background:linear-gradient(120deg,#fff,#f3faff)"><div class="flex" style="margin-bottom:11px"><span class="kpi-icon">${ico('spark')}</span><div><h2 style="margin:0">Que recherchez-vous ?</h2><small>Recherche sémantique simulée sur les profils fictifs</small></div></div><form id="smart-search-form" class="flex"><input class="input" style="flex:1;height:47px" id="smart-query" placeholder="Ex. Développeur Python Django avec 3 ans d'expérience à Casablanca" value="${E(ui.smartSearch)}"><button class="btn btn-primary" type="submit">${ico('search')} Rechercher</button></form><div class="tags" style="margin-top:14px">${['Développeur Python Django','Data Scientist NLP SQL','Chef de projet Agile','Ingénieur DevOps Docker'].map(x=>`<button class="tag" data-action="smart-example:${E(x)}">${E(x)}</button>`).join('')}</div></div><div class="card card-pad mt">${cardHead(q?`Résultats pour « ${E(q)} »`:'Profils à découvrir',`${res.length} profils · score de proximité textuelle démonstratif`)}${res.length?`<div class="grid grid-3">${res.slice(0,15).map(({c,score})=>`<article class="card" style="padding:17px;box-shadow:none"><div class="flex">${avatar(c,43)}<div><strong>${E(c.name)}</strong><small style="display:block;margin-top:4px">${E(c.role)}</small></div></div><div style="margin:15px 0 13px">${skilltags(c.skills,4)}</div><div class="info-pair"><span>Expérience</span><strong>${c.experience} ans</strong></div><div class="info-pair"><span>Localisation</span><strong>${E(c.city)}</strong></div><div class="flex" style="margin-top:14px;justify-content:space-between">${pill(q?`${score} critère(s) trouvé(s)`:'Profil disponible','green')}<button class="btn btn-sm" data-action="go:/candidates/${c.id}">Profil ${ico('arrow-right')}</button></div></article>`).join('')}</div>`:`<div class="empty">${ico('search')}<h3>Aucune correspondance identifiée</h3><p>Essayez un métier ou une compétence plus générale.</p></div>`}</div>`}
function matchingPage(){const job=getJ(ui.matchJob)||db.jobs[0];const candidates=sortedMatches(job);return heading('INTELLIGENCE RH / MATCHING','Matching sémantique','Identifiez les proximités entre compétences documentées et exigences des postes.',btn(`${ico('plus')} Créer une offre`,'go:/jobs/new'))+`<div class="notice mb">${ico('shield')} <span><b>Aide à la décision uniquement.</b> Scores démonstratifs calculés à partir de 75 % de correspondance des compétences et 25 % d'expérience attendue. Pas de décision automatique de recrutement.</span></div><div class="grid" style="grid-template-columns:minmax(230px,.85fr) minmax(0,1.8fr)"><aside class="card card-pad">${cardHead('Poste recherché','Sélectionnez une offre')}<div class="field"><label>Offre d'emploi</label><select class="select" id="match-job" style="width:100%">${db.jobs.map(j=>`<option value="${j.id}" ${job.id===j.id?'selected':''}>${E(j.title)}</option>`).join('')}</select></div><div style="margin-top:20px"><h3>${E(job.title)}</h3><p class="muted" style="font-size:11.5px;line-height:1.6">${E(job.description)}</p><div class="info-pair"><span>Ville</span><strong>${E(job.city)}</strong></div><div class="info-pair"><span>Expérience cible</span><strong>${job.experience} ans</strong></div><div class="info-pair"><span>Contrat</span><strong>${E(job.contract)}</strong></div><h3 style="margin-top:20px">Compétences requises</h3>${skilltags(job.skills,9)}<div style="margin-top:22px">${btn(`${ico('eye')} Détail du poste`,'go:/jobs/'+job.id,false,'btn-block')}</div></div></aside><section class="card card-pad">${cardHead('Classement des correspondances',`${candidates.length} profils examinés · score indicatif`,btn(`${ico('layers')} Comparer la sélection`,'compare',false,'btn-sm'))}<div class="table-wrap"><table class="data-table"><thead><tr><th></th><th>Profil</th><th>Compétences</th><th>Écarts</th><th>Proximité</th><th></th></tr></thead><tbody>${candidates.slice(0,12).map(({c,score,found,missing})=>`<tr><td><input type="checkbox" class="compare-checkbox" data-id="${c.id}" ${ui.selectedCompare.includes(c.id)?'checked':''}></td><td><div class="flex">${avatar(c,31)}<div><div class="candidate-name">${E(c.name)}</div><small>${E(c.role)} · ${c.experience} ans</small></div></div></td><td>${skilltags(found,3)}</td><td>${missing.length?`<small>${E(missing.join(', '))}</small>`:pill('Aucun','green')}</td><td><strong style="color:#0879be;font-size:15px">${score}%</strong><div class="progress-track" style="width:85px;margin-top:6px"><div class="progress-fill" style="width:${score}%"></div></div></td><td><button class="icon-btn" data-action="go:/candidates/${c.id}">${ico('chevron')}</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
function jobsPage(){const arr=db.jobs.filter(j=>ui.jobFilter==='all'||j.status===ui.jobFilter);return heading('RECRUTEMENT / OFFRES','Offres d’emploi','Gérez les opportunités et trouvez les candidats correspondants.',btn(`${ico('plus')} Nouvelle offre`,'go:/jobs/new',true))+`<div class="card card-pad"><div class="toolbar"><select class="select" id="job-filter"><option value="all">Toutes les offres</option><option ${ui.jobFilter==='Active'?'selected':''}>Active</option><option ${ui.jobFilter==='Brouillon'?'selected':''}>Brouillon</option><option ${ui.jobFilter==='Clôturée'?'selected':''}>Clôturée</option></select><div class="muted" style="margin-left:auto">${arr.length} offres</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Réf.</th><th>Intitulé</th><th>Département</th><th>Ville</th><th>Expérience</th><th>Statut</th><th>Actions</th></tr></thead><tbody>${arr.map(j=>`<tr><td>OFF-${String(j.id).padStart(3,'0')}</td><td><a class="candidate-name link" href="#/jobs/${j.id}">${E(j.title)}</a></td><td>${E(j.department)}</td><td>${E(j.city)}</td><td>${j.experience} ans</td><td>${badgeStatus(j.status)}</td><td><div class="flex" style="gap:4px"><button class="btn btn-sm" data-action="match-job:${j.id}">${ico('brain')} Matching</button><button class="icon-btn" data-action="go:/jobs/${j.id}">${ico('eye')}</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function jobFormPage(){return heading('OFFRES / CRÉATION','Créer une offre d’emploi','Renseignez les critères du poste qui serviront au matching.',btn(`${ico('arrow-left')} Retour`,'go:/jobs'))+`<div class="card card-pad" style="max-width:900px"><form id="job-create" class="form-grid"><div class="field full"><label>Intitulé du poste *</label><input required name="title" class="input" placeholder="Ex. Ingénieur Data / IA"></div><div class="field"><label>Entreprise</label><input name="company" class="input" placeholder="Ex. Atlas Digital"></div><div class="field"><label>Département</label><input name="department" class="input" placeholder="Ex. Ingénierie"></div><div class="field"><label>Ville</label><input name="city" class="input" placeholder="Ex. Marrakech"></div><div class="field"><label>Années d'expérience souhaitées</label><input name="experience" class="input" type="number" min="0" max="45" value="3"></div><div class="field"><label>Contrat</label><select name="contract" class="select"><option>CDI</option><option>CDD</option><option>Freelance</option><option>Stage</option></select></div><div class="field"><label>Date d'expiration</label><input name="expiresAt" class="input" type="date"></div><div class="field"><label>Degré d'urgence</label><select name="urgency" class="select"><option>Normale</option><option>Élevée</option><option>Urgente</option></select></div><div class="field full"><label>Compétences requises (séparées par virgules) *</label><input required name="skills" class="input" placeholder="Python, SQL, Machine Learning, Django"></div><div class="field full"><label>Description</label><textarea name="description" class="textarea" placeholder="Contexte du poste et profil recherché"></textarea></div><div class="field full"><label>Missions</label><textarea name="missions" class="textarea" placeholder="Missions du poste"></textarea></div><div class="field full" style="flex-direction:row;justify-content:flex-end;gap:9px">${btn('Annuler','go:/jobs')}<button type="submit" class="btn btn-primary">${ico('check')} Enregistrer l'offre</button></div></form></div>`}
function jobDetailPage(id){const j=getJ(id);if(!j)return '<div class="card card-pad">Offre introuvable</div>';const top=sortedMatches(j).slice(0,5);return heading('OFFRES / FICHE','Détail de l’offre',`OFF-${String(j.id).padStart(3,'0')} · ${j.created}`,`${btn(`${ico('arrow-left')} Toutes les offres`,'go:/jobs')}${btn(`${ico('brain')} Matching de cette offre`,'match-job:'+j.id,true)}`)+`<div class="grid col-main"><div class="card card-pad">${cardHead(E(j.title),'Poste et critères de recherche',badgeStatus(j.status))}<div class="grid grid-3" style="margin:18px 0">${[['Entreprise',j.company||'Non renseignée'],['Date d’expiration',j.expiresAt?fmtDate(j.expiresAt):'Non définie'],['Degré d’urgence',j.urgency||'Normale'],['Département',j.department],['Lieu',j.city],['Expérience',j.experience+' ans'],['Contrat',j.contract],['Statut',j.status],['Date de création',fmtDate(j.created)]].map(([k,v])=>`<div class="mini-stat"><span>${k}</span><div style="font-weight:800;margin-top:5px">${E(v)}</div></div>`).join('')}</div><p class="muted" style="line-height:1.75">${E(j.description)}</p><h3 style="margin-top:23px">Missions principales</h3><p class="muted" style="line-height:1.75">${E(j.missions)}</p><h3 style="margin-top:23px">Compétences attendues</h3>${skilltags(j.skills,12)}</div><aside class="card card-pad">${cardHead('Meilleures proximités','Données de démonstration')}${top.map(({c,score})=>`<div class="list-row">${avatar(c,35)}<div class="grow"><strong>${E(c.name)}</strong><small>${E(c.role)}</small></div><span class="badge green">${score}%</span><button class="icon-btn" data-action="go:/candidates/${c.id}">${ico('chevron')}</button></div>`).join('')}<div style="margin-top:18px">${btn('Comparer les profils','match-job:'+id,false,'btn-block')}</div></aside></div>`}
function recruitmentPage(){const selected=ui.recruitmentJob==='all'?null:getJ(ui.recruitmentJob);const pipeline=db.pipeline.filter(p=>!selected||p.jobId===selected.id);return heading('RECRUTEMENT / PIPELINE','Suivi des recrutements',selected?`Suivi de l'offre « ${selected.title} » · ${pipeline.length} candidature(s)`: 'Choisissez une offre pour afficher son pipeline.',btn(`${ico('plus')} Ajouter au pipeline`,'new-pipeline',true))+`<div class="card card-pad mb"><div class="toolbar"><label class="field" style="min-width:280px;margin:0"><span style="font-size:11px;font-weight:700;color:#607289">Offre à suivre</span><select class="select" id="recruitment-job" style="margin-top:7px"><option value="all">Sélectionner une offre</option>${db.jobs.map(j=>`<option value="${j.id}" ${ui.recruitmentJob===j.id?'selected':''}>${E(j.title)} · ${E(j.company||'Entreprise non renseignée')}</option>`).join('')}</select></label>${selected?`<div class="muted" style="margin-left:auto">${E(selected.company||'Entreprise non renseignée')} · ${E(selected.city)} · ${E(selected.urgency||'Normale')}</div>`:''}</div></div>${selected?`<div class="notice mb">${ico('move')} Glissez une candidature d'une colonne à l'autre, ou utilisez le menu de statut sur sa carte. Les changements sont enregistrés localement pour cette offre.</div><div class="kanban">${stages.map((stage,i)=>{const arr=pipeline.filter(p=>p.stage===stage);return `<div class="kanban-col" data-stage="${E(stage)}"><div class="kanban-top"><span style="display:flex;gap:7px;align-items:center"><i style="background:${['#4599d9','#1da99d','#a37bda','#e0a049','#c47dc6','#23a78d','#9ea6b1'][i]};height:8px;width:8px;border-radius:50%"></i>${E(stage)}</span><em>${arr.length}</em></div>${arr.map(p=>{const c=getC(p.candidateId),j=getJ(p.jobId);if(!c)return '';return `<div class="kanban-card" draggable="true" data-pid="${p.id}"><div class="flex" style="margin-bottom:10px">${avatar(c,30)}<span class="badge gray">#${p.id}</span></div><h4>${E(c.name)}</h4><p>${E(j?.title||'Candidature libre')}</p><footer><button class="btn btn-xs" data-action="go:/candidates/${c.id}">Profil</button><select class="select pipeline-select" data-pid="${p.id}" style="max-width:126px;height:28px;min-height:28px;padding:3px;font-size:9px">${stages.map(s=>`<option ${stage===s?'selected':''}>${s}</option>`).join('')}</select></footer></div>`}).join('')}${!arr.length?'<p style="font-size:10px;color:#9ba7b2;text-align:center;padding:25px 0">Aucune candidature</p>':''}</div>`}).join('')}</div>`:`<div class="card card-pad mk-empty">${ico('briefcase')}<strong>Sélectionnez une offre</strong><p>Le Kanban affichera uniquement les candidats affectés à cette offre.</p></div>`}`}
// MKLEAN v2 - Données et interfaces multicanales (démonstration uniquement)
function contactEvent(candidateId,channel,kind,direction,summary,source){return {id:Date.now()+Math.floor(Math.random()*9999),candidateId,channel,kind,direction,summary,source,at:today,owner:'Recruteur démo',status:source.includes('Simulation')?'Simulé':source.includes('Archive')?'Importé':source==='Interne MKLEAN'?'Confirmé interne':'Déclaré',jobId:null}}
function initialContacts(){return [
{id:101,candidateId:1,channel:'WhatsApp',kind:'Message reçu',direction:'entrant',summary:'Bonjour, je vous transmets mon CV actualisé.',source:'Simulation – webhook non connecté',at:'2026-10-30',owner:'Recruteur démo',status:'Simulé'},
{id:102,candidateId:1,channel:'WhatsApp',kind:'Message envoyé',direction:'sortant',summary:'Merci, pouvons-nous organiser un entretien ?',source:'Simulation – non transmis',at:'2026-10-30',owner:'Recruteur démo',status:'Simulé'},
{id:103,candidateId:2,channel:'LinkedIn',kind:'Invitation envoyée',direction:'sortant',summary:'Prise de contact pour une mission frontend.',source:'Déclaration manuelle',at:'2026-10-26',owner:'Recruteur démo',status:'Déclaré'},
{id:104,candidateId:3,channel:'LinkedIn',kind:'Réponse reçue',direction:'entrant',summary:'Intéressée par un échange sur les opportunités.',source:'Déclaration manuelle',at:'2026-10-28',owner:'Recruteur démo',status:'Déclaré'},
{id:105,candidateId:4,channel:'LinkedIn',kind:'Message envoyé',direction:'sortant',summary:'Présentation d’une opportunité Django.',source:'Déclaration manuelle',at:'2026-10-22',owner:'Recruteur démo',status:'Déclaré'},
{id:106,candidateId:5,channel:'Email',kind:'Email envoyé',direction:'sortant',summary:'Invitation à participer à un entretien.',source:'Déclaration manuelle',at:'2026-10-24',owner:'Recruteur démo',status:'Déclaré'},
{id:107,candidateId:6,channel:'Téléphone',kind:'Appel effectué',direction:'sortant',summary:'Appel de qualification et disponibilité.',source:'Déclaration manuelle',at:'2026-10-29',owner:'Recruteur démo',status:'Déclaré'},
{id:108,candidateId:7,channel:'Entretien',kind:'Entretien réalisé',direction:'interne',summary:'Entretien de présélection RH (simulation).',source:'Déclaration manuelle',at:'2026-10-30',owner:'Recruteur démo',status:'Déclaré'}]}
function linkedinLink(value){try{const u=new URL(value);return u.protocol==='https:'&&['linkedin.com','www.linkedin.com'].includes(u.hostname)&&/^\/in\/[a-zA-Z0-9%_-]+\/?/.test(u.pathname)?u.href:null}catch(e){return null}}
function simpleHash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return(h>>>0).toString(36)}
function csvFields(line){const out=[];let quoted=false,v='';for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){v+='"';i++}else quoted=!quoted}else if((c===','||c===';')&&!quoted){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out}
function parseArchiveCSV(csv){const lines=csv.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)return [];const headers=csvFields(lines[0]).map(norm);const pick=(row,options)=>{const ind=headers.findIndex(h=>options.some(o=>h===o||h.includes(o)));return ind>=0?row[ind]||'':''};return lines.slice(1,201).map((line,i)=>{const r=csvFields(line);return {line:i+2,name:pick(r,['nom','name','participant','profile']),type:pick(r,['type','action','event','evenement','invitation']),date:pick(r,['date','time','horodatage']),summary:pick(r,['message','contenu','content','texte','summary'])}}).filter(x=>x.name)}
function passiveCandidates(){const threshold=Number(db.settings.followupDays||5);return db.candidates.filter(c=>{const e=db.contacts.filter(x=>x.candidateId===c.id&&(x.channel==='LinkedIn'||x.channel==='WhatsApp')).sort((a,b)=>String(b.at).localeCompare(String(a.at)));if(!e.length)return false;const last=e[0];return last.direction==='sortant'&&last.at&&Math.round((Date.parse(today)-Date.parse(last.at))/86400000)>=threshold&&!db.candidateConsents[c.id]})}
function contactList(candidateId=null,channel='all'){return [...db.contacts].filter(e=>(candidateId===null||e.candidateId===candidateId)&&(channel==='all'||e.channel===channel)).sort((a,b)=>String(b.at).localeCompare(String(a.at))||b.id-a.id)}
function interactionRows(events){if(!events.length)return `<div class="empty">Aucune interaction enregistrée pour ce filtre.</div>`;return events.map(ev=>{const c=getC(ev.candidateId);return `<div class="mc-event"><span class="mc-icon">${ico(ev.channel==='LinkedIn'?'external':ev.channel==='WhatsApp'?'phone':ev.channel==='Email'?'mail':ev.channel==='Entretien'?'calendar':'phone')}</span><div class="grow"><div class="flex" style="justify-content:space-between;gap:10px;flex-wrap:wrap"><strong>${E(ev.kind)}</strong><span class="badge">${E(ev.channel)}</span></div><p>${E(ev.summary||'Sans commentaire')}</p><small>${E(c?.name||'Candidat')} · ${E(ev.at)} · ${E(ev.owner||'Équipe RH')} · ${E(ev.source)}</small></div><span class="badge ${ev.status==='Simulé'?'':'status-tag'}">${E(ev.status||'Déclaré')}</span></div>`}).join('')}
function followupList(cid=null){const tasks=db.followUps.filter(t=>(cid===null||t.candidateId===cid)&&t.status!=='Terminée');return tasks.length?tasks.map(t=>`<div class="mc-event"><span class="mc-icon">${ico('clock')}</span><div class="grow"><strong>${E(getC(t.candidateId)?.name||'Candidat')}</strong><p>${E(t.reason)}</p><small>À faire ${E(t.due)} · ${E(t.channel)} · ${E(t.owner)}</small></div><button class="btn btn-sm" data-action="followup-done:${t.id}">${ico('check')} Terminer</button></div>`).join(''):'<p class="muted-small">Aucune relance ouverte.</p>'}
function communicationPanel(c){return `<div class="grid col-main"><section class="card card-pad">${cardHead('Timeline multicanale','Canaux et provenance de chaque interaction',btn(`${ico('plus')} Nouvelle interaction`,'new-contact:LinkedIn:'+c.id,true))}${interactionRows(contactList(c.id))}</section><aside class="card card-pad">${cardHead('Relation candidat')}${[['Profil LinkedIn',c.linkedinUrl?'Renseigné':'À renseigner'],['WhatsApp',c.phone],['Interactions',contactList(c.id).length],['Opposition',db.candidateConsents[c.id]?'Oui':'Non']].map(([l,v])=>`<div class="info-pair"><span>${E(l)}</span><strong>${E(v)}</strong></div>`).join('')}<div class="mc-actions">${btn('Associer LinkedIn','link-linkedin:'+c.id)}${btn('Historique global','go:/communications/timeline')}${btn('Créer une relance','followup-create:'+c.id,true)}</div><h3 style="margin-top:21px">Relances à effectuer</h3>${followupList(c.id)}</aside></div>`}
function linkedInPage(){const contacts=contactList(null,'LinkedIn');const opened=contacts.filter(e=>e.kind==='Ouverture de profil').length;const sent=contacts.filter(e=>e.kind.includes('Invitation')||e.kind.includes('Message envoyé')).length;const replies=contacts.filter(e=>e.kind.includes('Réponse')).length;const flt=ui.linkedInFilter;const arr=flt==='all'?contacts:contacts.filter(e=>flt==='declared'?e.source==='Déclaration manuelle':e.source?.includes('Archive'));return heading('SOURCING / LINKEDIN','Traçabilité LinkedIn','Suivez le sourcing effectué depuis MKLEAN et les interactions déclarées ou importées.',`${btn(`${ico('plus')} Déclarer une interaction`,'declare-linkedin',true)}`)+`<div class="notice warn mb">${ico('shield')} <span>LinkedIn n'est pas connecté. L'ouverture d'un lien depuis MKLEAN est traçable ; les invitations, messages et réponses restent déclarés/importés et ne sont pas synchronisés via API standard.</span></div><div class="grid grid-4">${[['Profils ouverts depuis MKLEAN',opened,'eye'],['Prises de contact enregistrées',sent,'mail'],['Réponses renseignées',replies,'check'],['Sans réponse ('+(db.settings.followupDays||5)+' j)',passiveCandidates().length,'clock']].map(([l,v,i])=>`<div class="card kpi"><div class="kpi-head"><div class="kpi-icon">${ico(i)}</div></div><div class="kpi-value">${v}</div><div class="kpi-label">${l}</div></div>`).join('')}</div><div class="grid col-main mt"><section class="card card-pad">${cardHead('Profils candidats','Associer une URL, puis enregistrer une ouverture via MKLEAN')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Candidat</th><th>Métier</th><th>Lien</th><th>Actions</th></tr></thead><tbody>${db.candidates.slice(0,12).map(c=>`<tr><td><a class="link" href="#/candidates/${c.id}">${E(c.name)}</a></td><td>${E(c.role)}</td><td>${c.linkedinUrl?pill('Associé','green'):pill('Non renseigné','gray')}</td><td><div class="flex"><button class="btn btn-sm" data-action="link-linkedin:${c.id}">${ico('edit')} Lier</button><button class="btn btn-sm" ${!c.linkedinUrl?'disabled':''} data-action="open-linkedin:${c.id}">${ico('external')} Ouvrir</button></div></td></tr>`).join('')}</tbody></table></div></section><aside><section class="card card-pad">${cardHead('Import d’archives LinkedIn','CSV pilote : correspondance sur le nom exact')}<p class="muted-small">Importer une archive appartenant à un compte autorisé ; les formats peuvent varier. Aperçu et rapprochement avant validation.</p><input type="file" id="linkedin-archive-file" accept=".csv,text/csv" style="display:none"><button class="btn btn-primary" data-action="import-linkedin">${ico('upload')} Sélectionner un CSV</button>${ui.archivePreview?`<div class="mc-preview"><strong>${E(ui.archivePreview.filename)}</strong><p>${ui.archivePreview.rows.length} lignes reconnues · ${ui.archivePreview.rows.filter(r=>db.candidates.some(c=>norm(c.name)===norm(r.name))).length} candidats rapprochés</p>${btn('Valider l’import','archive-commit',true)}</div>`:''}<div class="notice mt">${ico('info')} Colonnes pilotes : Nom (ou Name), Date, Type, Message. Les fichiers LinkedIn ne suivent pas tous ce modèle.</div></section><section class="card card-pad mt">${cardHead('Rappels LinkedIn')}${followupList()}</section></aside></div><section class="card card-pad mt">${cardHead('Historique LinkedIn','Distinction explicite entre événements déclarés et importés')}<div class="toolbar"><select class="select" id="linkedin-filter"><option value="all">Toutes les sources</option><option value="declared" ${flt==='declared'?'selected':''}>Déclarations manuelles</option><option value="archive" ${flt==='archive'?'selected':''}>Archives importées</option></select></div>${interactionRows(arr)}</section>`}
function whatsappPage(){const id=ui.waCandidateId;const c=getC(id)||db.candidates[0],messages=contactList(c.id,'WhatsApp').sort((a,b)=>String(a.at).localeCompare(String(b.at))||a.id-b.id);const wa=contactList(null,'WhatsApp');const people=[...new Set(wa.map(x=>x.candidateId))];if(!people.includes(id))people.push(id);return heading('COMMUNICATION / WHATSAPP','WhatsApp Business','Boîte de réception et gestion des CV entrants — simulation sans connexion API.',btn(`${ico('plus')} Déclarer une interaction`,'new-contact:WhatsApp:'+c.id,true))+`<div class="notice warn mb">${ico('info')} <span>Aucun compte Meta n'est connecté : les messages affichés et envoyés sont fictifs. En production, l'envoi requiert opt-in, modèles approuvés hors fenêtre de 24 h et API officielle Meta.</span></div><div class="grid grid-4">${[['Conversations de démonstration',people.length,'users'],['Messages sortants',wa.filter(x=>x.direction==='sortant').length,'mail'],['Messages entrants',wa.filter(x=>x.direction==='entrant').length,'phone'],['Réponses enregistrées',wa.filter(x=>x.kind.includes('reçu')).length,'check']].map(([l,v,i])=>`<div class="card kpi"><div class="kpi-head"><div class="kpi-icon">${ico(i)}</div></div><div class="kpi-value">${v}</div><div class="kpi-label">${l}</div></div>`).join('')}</div><div class="mc-inbox mt"><aside class="card card-pad mc-sidebar">${cardHead('Conversations','Choisir un candidat')}${people.map(cid=>{const cp=getC(cid);const last=contactList(cid,'WhatsApp')[0];return `<button class="mc-thread ${cid===id?'is-active':''}" data-action="wa-select:${cid}">${avatar(cp,34)}<span><strong>${E(cp.name)}</strong><small>${E(last?.kind||'Nouvelle conversation')}</small></span></button>`}).join('')}</aside><section class="card card-pad mc-chat"><div class="mc-chat-header"><div class="flex">${avatar(c,42)}<div><strong>${E(c.name)}</strong><small>${E(c.phone)} · Conversation fictive</small></div></div><button class="btn btn-sm" data-action="go:/candidates/${c.id}">Fiche candidat</button></div><div class="mc-messages">${messages.length?messages.map(m=>`<div class="mc-bubble ${m.direction==='sortant'?'sent':'received'}"><p>${E(m.summary)}</p><small>${E(m.at)} · ${E(m.source)}</small></div>`).join(''):'<div class="empty">Aucun message. Ajoutez un message fictif.</div>'}</div><form id="wa-compose" class="mc-compose"><input type="hidden" name="candidateId" value="${c.id}"><input class="input" name="message" required placeholder="Écrire un message de démonstration…" ${db.candidateConsents[c.id]?'disabled':''}><button class="btn btn-primary" ${db.candidateConsents[c.id]?'disabled':''} type="submit">${ico('arrow-right')} Simuler</button></form><div class="mc-actions"><button class="btn btn-sm" data-action="wa-receive:${c.id}">Simuler une réponse</button><input type="file" id="whatsapp-cv-file" accept=".pdf,.docx" aria-label="Ajouter un CV fictif"><button class="btn btn-sm ${db.candidateConsents[c.id]?'btn-primary':'btn-danger'}" data-action="toggle-optout:${c.id}">${db.candidateConsents[c.id]?'Opposition enregistrée':'Enregistrer opt-out'}</button></div><p class="muted-small">Fichiers locaux : seule la référence du nom est conservée en démo. L'API, le parsing CV et le stockage documentaire restent à développer.</p></section></div>`}
function communicationsPage(){const arr=contactList(null,ui.channelFilter),total=db.contacts.length;return heading('RELATION CANDIDAT / MULTICANAL','Historique des interactions','LinkedIn, WhatsApp, téléphone, email et entretiens dans une chronologie partagée.',btn(`${ico('plus')} Ajouter une interaction`,'new-contact:Email:1',true))+`<div class="grid grid-4">${[['Événements consignés',total,'timeline'],['LinkedIn',db.contacts.filter(x=>x.channel==='LinkedIn').length,'external'],['WhatsApp',db.contacts.filter(x=>x.channel==='WhatsApp').length,'phone'],['Relances ouvertes',db.followUps.filter(x=>x.status!=='Terminée').length,'clock']].map(([l,v,i])=>`<div class="card kpi"><div class="kpi-head"><div class="kpi-icon">${ico(i)}</div></div><div class="kpi-value">${v}</div><div class="kpi-label">${l}</div></div>`).join('')}</div><div class="grid col-main mt"><section class="card card-pad">${cardHead('Timeline multicanale',`${arr.length} événement(s), avec source et statut`)}<div class="toolbar"><select class="select" id="channel-filter"><option value="all">Tous les canaux</option>${['LinkedIn','WhatsApp','Email','Téléphone','Entretien'].map(ch=>`<option ${ui.channelFilter===ch?'selected':''}>${E(ch)}</option>`).join('')}</select>${btn('Exporter les événements','export-contacts')}</div>${interactionRows(arr)}</section><aside><section class="card card-pad">${cardHead('Relances et candidats passifs','Rappels internes, sans envoi automatique')}${passiveCandidates().map(c=>`<div class="mc-event"><div class="grow"><strong>${E(c.name)}</strong><p>Sans réponse après ${db.settings.followupDays||5} jours (démo)</p></div><button class="btn btn-sm" data-action="followup-create:${c.id}">Relancer</button></div>`).join('')}${followupList()}<p class="muted-small">Le statut « sans réponse » repose sur une période paramétrable et n'évalue pas la motivation du candidat.</p></section><section class="card card-pad mt">${cardHead('Garanties de traçabilité')}${[['Déclarée','Action saisie par recruteur'],['Importée','Événement présent dans archive'],['Simulée','Aucun message réel transmis']].map(([a,b])=>`<div class="info-pair"><span>${E(a)}</span><strong>${E(b)}</strong></div>`).join('')}</section></aside></div>`}
function enrichmentSources(c){return [{id:'portfolio',name:'Portfolio professionnel',origin:'URL déclarée par le candidat',desc:'Portfolio et réalisations professionnelles · source simulée',url:'https://portfolio.example/profil',skill:c.skills[0]},{id:'github',name:'Dépôts GitHub publics',origin:'Source publique autorisée',desc:'Projets logiciels, contributions et documentation · source simulée',url:'https://github.example/compte',skill:c.skills[1]},{id:'cert',name:'Certification professionnelle',origin:'Organisme certificateur',desc:'Référence de certification à confirmer · source simulée',url:'https://certification.example/verifier',skill:c.skills[2]},{id:'article',name:'Publication professionnelle',origin:'Site public autorisé',desc:'Article ou contribution professionnelle · source simulée',url:'https://publication.example/article',skill:c.skills[3]}]}
function enrichmentPage(id){const c=getC(id);if(!c)return '<div class="card card-pad">Candidat introuvable</div>';const source=enrichmentSources(c);const approved=db.approvedSources[id]||[];return heading('CANDIDATS / ENRICHISSEMENT','Enrichissement du profil',`Sources professionnelles autorisées pour ${c.name}`,`${btn(`${ico('arrow-left')} Fiche candidat`,'go:/candidates/'+c.id)}${btn(`${ico('refresh')} Rechercher des sources (démo)`,'simulate-sources',true)}`)+`<div class="notice warn mb">${ico('shield')} <span><b>Mode démonstration :</b> aucune collecte web réelle n'est effectuée. Les URL et les résultats sont fictifs. Toute collecte réelle nécessiterait un cadre légal, un contrôle des sources et une information appropriée du candidat.</span></div><div class="grid col-main"><div class="card card-pad">${cardHead('Sources d’enrichissement proposées',`${source.length} sources fictives à examiner`)}${source.map(s=>`<div class="source-card"><div class="source-icon">${ico(s.id==='github'?'database':s.id==='cert'?'award':'globe')}</div><div class="grow"><h3>${E(s.name)}</h3><p>${E(s.desc)}</p><small>${E(s.origin)} · Compétence associée : ${E(s.skill)}</small><div style="margin-top:9px">${pill(approved.includes(s.id)?'Validée par le recruteur':'À confirmer',approved.includes(s.id)?'green':'orange')}</div></div><button class="btn btn-sm" data-action="approve-source:${id}:${s.id}">${ico(approved.includes(s.id)?'close':'check')} ${approved.includes(s.id)?'Annuler':'Valider'}</button></div>`).join('')}</div><aside><div class="card card-pad">${cardHead('Contrôle et traçabilité')}${[['Sources identifiées',source.length],['Sources validées',approved.length],['En attente',source.length-approved.length]].map(([l,v])=>`<div class="info-pair"><span>${l}</span><strong>${v}</strong></div>`).join('')}<h3 style="margin-top:22px">Processus d'enrichissement</h3>${['Identifier des sources autorisées','Examiner les données','Vérifier la provenance','Valider manuellement','Rattacher au profil'].map((t,i)=>`<div class="list-row"><span class="badge">${i+1}</span><div class="grow"><strong>${t}</strong></div></div>`).join('')}</div></aside></div>`}
function reportsPage(){const jobs=db.jobs.length,validated=db.candidates.filter(c=>c.validated).length,n=db.candidates.length;const byCity=cities.map(city=>({city,n:db.candidates.filter(c=>c.city===city).length}));const topSkills=[...new Set(db.candidates.flatMap(c=>c.skills))].map(s=>({s,n:db.candidates.filter(c=>c.skills.includes(s)).length})).sort((a,b)=>b.n-a.n).slice(0,7);return heading('ANALYSE / RAPPORTS','Rapports & statistiques','Indicateurs analytiques issus du jeu de données fictif.',btn(`${ico('download')} Exporter CSV`,'export-report',true))+`<div class="grid grid-4">${[['Profils disponibles',n,'users'],['Profils vérifiés',validated,'shield'],['Offres créées',jobs,'briefcase'],['Candidatures en suivi',db.pipeline.length,'kanban']].map(([l,v,ic])=>`<div class="card kpi"><div class="kpi-head"><div class="kpi-icon">${ico(ic)}</div></div><div class="kpi-value">${v}</div><div class="kpi-label">${l}</div></div>`).join('')}</div><div class="grid col-main mt"><section class="card card-pad">${cardHead('Distribution des profils','Répartition géographique dans la CVthèque')}${byCity.map(c=>`<div class="skill-progress" style="margin:17px 0"><span>${E(c.city)}</span><div class="progress-track"><div class="progress-fill" style="width:${c.n/n*100}%"></div></div><strong>${c.n}</strong></div>`).join('')}</section><section class="card card-pad">${cardHead('Statut des profils','Validation documentaire')}<div class="report-ring" style="background:conic-gradient(#1484d2 0 ${Math.round(validated/n*100)}%,#f3bf68 ${Math.round(validated/n*100)}% 100%)"><span>${Math.round(validated/n*100)}%</span></div><div class="legend"><span><i style="background:#1484d2"></i>Profils vérifiés</span><strong>${validated}</strong></div><div class="legend"><span><i style="background:#f3bf68"></i>À vérifier</span><strong>${n-validated}</strong></div></section></div><div class="grid col-main mt"><section class="card card-pad">${cardHead('Compétences les plus fréquentes','Mentionnées dans les profils fictifs')}${topSkills.map(x=>`<div class="skill-progress"><span>${E(x.s)}</span><div class="progress-track"><div class="progress-fill" style="width:${x.n/topSkills[0].n*100}%"></div></div><strong>${x.n}</strong></div>`).join('')}</section><section class="card card-pad">${cardHead('Pipeline de recrutement','Répartition par étape')}${stages.map(s=>`<div class="list-row"><span class="grow"><strong>${E(s)}</strong></span><span class="badge">${db.pipeline.filter(p=>p.stage===s).length}</span></div>`).join('')}</section></div>`}
function settingsPage(){const tabs=[['general','Général'],['users','Utilisateurs'],['referential','Référentiels'],['ai','Matching & IA'],['privacy','Confidentialité'],['multichannel','Multicanal']];let body='';if(ui.settingsTab==='general')body=`${settingsRow('Notifications des activités','Afficher des notifications de démonstration.','notifications')}${settingsRow('Vérification humaine','Validation des données et des sources enrichies.','manualReview')}${settingsRow('Moteur IA local','Préférence d’architecture : traitement local (non connecté en démo).','localAI')}`;
else if(ui.settingsTab==='users')body=`<div class="notice mb">${ico('info')} Gestion des rôles simulée. Les autorisations doivent être sécurisées dans le backend en production.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Utilisateur</th><th>Fonction</th><th>Rôle</th><th>Statut</th></tr></thead><tbody>${[['Administrateur démo','Supervision de la plateforme','Administrateur'],['Responsable RH','Pilotage des recrutements','Responsable RH'],['Recruteur démo','Gestion des candidatures','Recruteur'],['Lecteur démo','Consultation autorisée','Lecteur']].map(([u,r,role])=>`<tr><td><strong>${u}</strong></td><td>${r}</td><td>${pill(role)}</td><td>${pill('Démo','green')}</td></tr>`).join('')}</tbody></table></div>`;
else if(ui.settingsTab==='referential')body=`<div class="grid grid-2"><div><h3>Compétences du référentiel</h3><div class="tags" style="margin-top:13px">${[...new Set(db.candidates.flatMap(c=>c.skills))].slice(0,35).map(s=>`<span class="tag">${E(s)}</span>`).join('')}</div></div><div><h3>Familles de métiers</h3>${['Ingénierie logicielle','Données & IA','Ressources humaines','Infrastructure & Cloud','Gestion de projet','Design & expérience utilisateur','Sécurité'].map(t=>`<div class="list-row"><span class="grow">${t}</span>${pill('Actif','green')}</div>`).join('')}</div></div>`;
else if(ui.settingsTab==='ai')body=`<div class="notice mb">${ico('brain')} Exemple de pondération indicative et transparente : 75 % compétences, 25 % expérience. Le paramétrage n’a pas valeur de validation scientifique.</div><div class="settings-row"><div><strong>Correspondance des compétences</strong><p>Poids dans le score de proximité</p></div><span class="badge">75 %</span></div><div class="settings-row"><div><strong>Expérience pertinente</strong><p>Poids dans le score de proximité</p></div><span class="badge">25 %</span></div>${settingsRow('Traitement local privilégié','L’architecture locale est une option pour la future version.','localAI')}`;
else if(ui.settingsTab==='multichannel')body=`<div class="notice warn mb">${ico('info')} Réglages de démonstration. La connexion WhatsApp réelle exige l’API officielle Meta et ses autorisations ; LinkedIn ne donne pas accès par défaut à la messagerie privée.</div><div class="settings-row"><div><strong>Délai de classification sans réponse</strong><p>Nombre de jours depuis le dernier contact sortant sans réponse.</p></div><input class="input" id="followup-days" type="number" style="max-width:100px" min="1" max="90" value="${db.settings.followupDays||5}"></div><div class="settings-row"><div><strong>LinkedIn</strong><p>Saisie et import d’archives autorisés, pas de synchronisation privée standard.</p></div>${pill('Mode manuel','orange')}</div><div class="settings-row"><div><strong>WhatsApp Business</strong><p>Conversation et CV : simulation sans compte Meta connecté.</p></div>${pill('Démo','gray')}</div>`;
else body=`<div class="notice warn mb">${ico('shield')} Les obligations légales et les formalités CNDP devront être examinées avant toute exploitation de données réelles.</div>${settingsRow('Contrôle avant enrichissement web','Enrichissement uniquement sur sources autorisées.','webConsent')}${settingsRow('Validation humaine','Conserver l’humain au centre des décisions de recrutement.','manualReview')}<div class="settings-row"><div><strong>Stockage de démonstration</strong><p>Les données et modifications sont stockées dans ce navigateur (localStorage).</p></div><button class="btn btn-danger" data-action="reset-demo">${ico('trash')} Réinitialiser</button></div>`;
return heading('ADMINISTRATION / PARAMÈTRES','Administration','Personnalisation, référentiels et gouvernance de la plateforme.',btn(`${ico('refresh')} Réinitialiser la démo`,'reset-demo'))+`<div class="card card-pad"><div class="subtabs">${tabs.map(([k,l])=>`<button class="subtab ${ui.settingsTab===k?'active':''}" data-action="settings-tab:${k}">${l}</button>`).join('')}</div>${body}</div>`}
function settingsRow(t,d,k){return `<div class="settings-row"><div><strong>${t}</strong><p>${d}</p></div><button class="switch ${db.settings[k]?'on':''}" aria-label="Basculer ${t}" aria-pressed="${db.settings[k]}" data-action="toggle-setting:${k}"></button></div>`}
function modalHtml(){const m=ui.modal;if(!m)return '';if(m.kind?.startsWith('mk-'))return mkExtraModal(m);let title='',body='',footer=`<button class="btn" data-action="modal-close">Fermer</button>`;
if(m.kind==='event'){const c=getC(m.id),x=c?.journey.find(y=>y.id===m.eventId);if(!x)return '';title=x.title;body=`<div class="flex" style="justify-content:space-between">${pill(x.type==='job'?'Expérience':x.type==='education'?'Formation':'Certification')}${pill(x.verified?'Confirmé':'À vérifier',x.verified?'green':'orange')}</div><div class="info-pair"><span>Période</span><strong>${x.start} – ${x.end}</strong></div><div class="info-pair"><span>Organisme / entreprise</span><strong>${E(x.org)}</strong></div><div class="info-pair"><span>Source</span><strong>${E(x.source)}</strong></div><p style="line-height:1.7;margin-top:17px">${E(x.description)}</p><h3>Compétences associées</h3>${skilltags(x.skills,12)}`}
else if(m.kind==='edit-candidate'||m.kind==='new-candidate'){const c=m.kind==='edit-candidate'?getC(m.id):null;title=c?'Modifier le candidat':'Nouveau candidat';body=`<form id="candidate-editor" class="form-grid"><input name="id" type="hidden" value="${c?.id||''}"><div class="field full"><label>Nom complet *</label><input class="input" name="name" required value="${E(c?.name||'')}"></div><div class="field full"><label>Métier / intitulé *</label><input class="input" name="role" required value="${E(c?.role||'')}"></div><div class="field"><label>Ville</label><input class="input" name="city" value="${E(c?.city||'Marrakech')}"></div><div class="field"><label>Expérience (années)</label><input class="input" name="experience" type="number" min="0" max="55" value="${c?.experience||0}"></div><div class="field full"><label>Compétences (virgules)</label><input class="input" name="skills" value="${E(c?.skills?.join(', ')||'')}"></div><div class="field full"><label>Formation</label><input class="input" name="education" value="${E(c?.education||'')}"></div><div class="field full"><label>Résumé professionnel</label><textarea class="textarea" name="bio">${E(c?.bio||'')}</textarea></div><div class="field full" style="flex-direction:row;justify-content:flex-end"><button class="btn" type="button" data-action="modal-close">Annuler</button><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`;footer=''}
else if(m.kind==='compare'){const j=getJ(ui.matchJob),cs=ui.selectedCompare.map(getC).filter(Boolean);title='Comparaison des candidats';if(cs.length<2){body='<div class="notice warn">Sélectionnez deux ou trois candidats dans le tableau de matching.</div>'}else body=`<div class="comparison"><div class="cmp-head">Critère</div>${cs.map(c=>`<div class="cmp-head">${E(c.name)}</div>`).join('')}<div>Métier</div>${cs.map(c=>`<div>${E(c.role)}</div>`).join('')}<div>Proximité illustrative</div>${cs.map(c=>`<div><strong style="color:#087ac9">${match(c,j).score}%</strong></div>`).join('')}<div>Expérience</div>${cs.map(c=>`<div>${c.experience} ans</div>`).join('')}<div>Compétences communes</div>${cs.map(c=>`<div>${skilltags(match(c,j).found,8)}</div>`).join('')}<div>Écarts documentés</div>${cs.map(c=>`<div>${skilltags(match(c,j).missing,8)}</div>`).join('')}</div><div class="notice mt">${ico('info')} Comparaison indicative sur données fictives. Toute décision doit être prise par un responsable habilité.</div>`}
else if(m.kind==='new-pipeline'){title='Ajouter une candidature au pipeline';body=`<form id="pipeline-add" class="form-grid"><div class="field full"><label>Candidat</label><select name="candidateId" class="select">${db.candidates.map(c=>`<option value="${c.id}">${E(c.name)} · ${E(c.role)}</option>`).join('')}</select></div><div class="field full"><label>Offre</label><select name="jobId" class="select">${db.jobs.map(j=>`<option value="${j.id}">${E(j.title)}</option>`).join('')}</select></div><div class="field full"><label>Étape initiale</label><select name="stage" class="select">${stages.map(s=>`<option>${E(s)}</option>`).join('')}</select></div><div class="field full" style="flex-direction:row;justify-content:flex-end"><button type="button" class="btn" data-action="modal-close">Annuler</button><button type="submit" class="btn btn-primary">Ajouter</button></div></form>`;footer=''}
else if(m.kind==='assign-job'){const c=getC(m.candidateId),j=getJ(m.jobId),existing=db.pipeline.find(p=>p.candidateId===c?.id&&p.jobId===j?.id);title=existing?'Affectation déjà enregistrée':'Valider l’affectation';body=`<form id="assign-job-form" class="form-grid"><input type="hidden" name="candidateId" value="${c?.id||''}"><input type="hidden" name="jobId" value="${j?.id||''}"><div class="notice full">${ico('briefcase')} <span><strong>${E(c?.name||'Candidat')}</strong> sera associé(e) à l’offre <strong>${E(j?.title||'Offre')}</strong> chez ${E(j?.company||'l’entreprise concernée')}.</span></div><div class="field full"><label>Étape de recrutement</label><select name="stage" class="select">${stages.map(s=>`<option ${existing?.stage===s||(!existing&&s==='Présélection')?'selected':''}>${E(s)}</option>`).join('')}</select></div><div class="field full" style="flex-direction:row;justify-content:flex-end"><button type="button" class="btn" data-action="modal-close">Annuler</button><button type="submit" class="btn btn-primary">${ico('check')} ${existing?'Mettre à jour':'Valider l’affectation'}</button></div></form>`;footer=''}
else if(m.kind==='job-preview'){const j=getJ(m.jobId);if(!j)return '';title=j.title;body=`<div class="details-row">${badgeStatus(j.status)}${pill(j.urgency||'Normale',j.urgency==='Urgente'?'red':j.urgency==='Élevée'?'orange':'green')}</div><div class="grid grid-2 mt"><div class="info-pair"><span>Entreprise</span><strong>${E(j.company||'Non renseignée')}</strong></div><div class="info-pair"><span>Expiration</span><strong>${E(j.expiresAt?fmtDate(j.expiresAt):'Non définie')}</strong></div><div class="info-pair"><span>Lieu</span><strong>${E(j.city)}</strong></div><div class="info-pair"><span>Contrat</span><strong>${E(j.contract)}</strong></div></div><h3 style="margin-top:20px">Description</h3><p style="line-height:1.75">${E(j.description)}</p><h3>Missions</h3><p style="line-height:1.75">${E(j.missions)}</p><h3>Compétences attendues</h3>${skilltags(j.skills,12)}<div style="margin-top:22px">${btn(`${ico('check')} Affecter ce candidat`,'assign-job:'+m.candidateId+':'+j.id,true,'btn-block')}</div>`}
else if(m.kind==='edit-journey'){const c=getC(m.id);title='Ajouter une étape au parcours';body=`<form id="journey-add" class="form-grid"><input name="id" value="${c.id}" type="hidden"><div class="field full"><label>Intitulé de l’étape *</label><input class="input" name="title" required placeholder="Ex. Chef de projet technique"></div><div class="field"><label>Type d’événement</label><select name="type" class="select"><option value="job">Expérience</option><option value="education">Formation</option><option value="certification">Certification</option></select></div><div class="field"><label>Organisme</label><input class="input" name="org" placeholder="Entreprise / établissement"></div><div class="field"><label>Année de début</label><input class="input" name="start" type="number" min="1950" max="2030" value="2025"></div><div class="field"><label>Année de fin</label><input class="input" name="end" type="number" min="1950" max="2030" value="2026"></div><div class="field full"><label>Compétences (virgules)</label><input class="input" name="skills" placeholder="Python, SQL"></div><div class="field full" style="flex-direction:row;justify-content:flex-end"><button type="button" class="btn" data-action="modal-close">Annuler</button><button type="submit" class="btn btn-primary">Ajouter l'étape</button></div></form>`;footer=''}
else if(m.kind==='link-linkedin'){const c=getC(m.id);title='Associer un profil LinkedIn';body=`<form id="link-linkedin-form" class="form-grid"><input type="hidden" name="id" value="${c.id}"><div class="field full"><label>Candidat</label><strong>${E(c.name)}</strong></div><div class="field full"><label>URL du profil *</label><input class="input" required type="url" name="url" value="${E(c.linkedinUrl||'')}" placeholder="https://www.linkedin.com/in/..."></div><div class="notice full">La plateforme journalise l'ouverture du lien depuis MKLEAN, pas les actions réalisées ensuite sur LinkedIn.</div><div class="field full" style="flex-direction:row;justify-content:flex-end"><button type="button" class="btn" data-action="modal-close">Annuler</button><button type="submit" class="btn btn-primary">Enregistrer</button></div></form>`;footer=''}
else if(m.kind==='new-contact'){const id=m.id||1;title='Déclarer une interaction';body=`<form id="contact-editor" class="form-grid"><div class="field full"><label>Candidat</label><select class="select" name="candidateId">${db.candidates.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="field"><label>Canal</label><select class="select" name="channel">${['LinkedIn','WhatsApp','Email','Téléphone','Entretien'].map(x=>`<option ${x===m.channel?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Nature</label><select class="select" name="kind">${['Invitation envoyée','Invitation acceptée','Message envoyé','Réponse reçue','Tentative de contact','Entretien réalisé','Non disponible','Intéressé','Refus / désinscription'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Sens</label><select class="select" name="direction"><option value="sortant">Sortant</option><option value="entrant">Entrant</option><option value="interne">Interne</option></select></div><div class="field"><label>Date</label><input class="input" type="date" name="at" value="${today}"></div><div class="field full"><label>Mission associée</label><select class="select" name="jobId"><option value="">Non associée</option>${db.jobs.map(j=>`<option value="${j.id}">${E(j.title)}</option>`).join('')}</select></div><div class="field full"><label>Résumé / déclaration</label><textarea class="textarea" name="summary" placeholder="Information déclarée par le recruteur et non vérifiée automatiquement"></textarea></div><div class="field full" style="flex-direction:row;justify-content:flex-end"><button class="btn" type="button" data-action="modal-close">Annuler</button><button class="btn btn-primary" type="submit">Enregistrer la déclaration</button></div></form>`;footer=''}
else if(m.kind==='confirm-reset'){title='Réinitialiser les données ?';body='<p>Cette action supprime toutes les modifications effectuées dans ce navigateur et restaure les candidats, les offres et les étapes du pipeline de démonstration.</p>';footer=`<button class="btn" data-action="modal-close">Annuler</button><button class="btn btn-danger" data-action="confirm-reset">Réinitialiser</button>`}
return `<div class="modal-backdrop" id="modal-bg"><div class="modal" role="dialog" aria-modal="true" aria-label="${E(title)}"><header class="modal-header"><div><div class="eyebrow">MKLEAN TALENT AI</div><h2>${E(title)}</h2></div><button class="icon-btn" data-action="modal-close">${ico('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</div></div>`}
function openModal(obj){ui.modal=obj;render()}
function csvDownload(name,records){const quoted=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv='\uFEFF'+records.map(row=>row.map(quoted).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function mkleanCvDownload(c){
 const jobs=c.journey.filter(x=>x.type==='job').slice().reverse();
 const html=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>CV MKLEAN - ${E(c.name)}</title><style>body{font-family:Arial,sans-serif;color:#18324d;margin:0;padding:42px;line-height:1.45}header{border-bottom:4px solid #087dcc;padding-bottom:20px;margin-bottom:24px}h1{margin:0;color:#0b355b;font-size:30px}h2{font-size:15px;text-transform:uppercase;letter-spacing:1px;color:#087dcc;border-bottom:1px solid #d9e8f3;padding-bottom:6px;margin-top:26px}.meta{color:#64788d;margin-top:7px}.skills span{display:inline-block;background:#eaf5fc;color:#176e9f;border-radius:12px;padding:5px 10px;margin:3px;font-size:12px}.job{margin:13px 0}.job strong{display:block;font-size:14px}.job small{color:#718397}</style></head><body><header><h1>${E(c.name)}</h1><div class="meta"><strong>${E(c.role)}</strong> · ${E(c.city)} · ${c.experience} ans d'expérience</div><div class="meta">${E(c.email)} · ${E(c.phone)}</div></header><h2>Profil</h2><p>${E(c.bio)}</p><h2>Compétences</h2><div class="skills">${c.skills.map(s=>`<span>${E(s)}</span>`).join('')}</div><h2>Expériences professionnelles</h2>${jobs.map(x=>`<div class="job"><strong>${E(x.title)} — ${E(x.org)}</strong><small>${E(x.start)} – ${E(x.end)}</small><div>${E(x.description||'Expérience professionnelle')}</div></div>`).join('')||'<p>À compléter</p>'}<h2>Formation</h2><p>${E(c.education)}</p><footer style="margin-top:35px;color:#91a0ae;font-size:11px">CV généré selon le template standardisé MKLEAN · ${today}</footer></body></html>`;
 const blob=new Blob([html],{type:'application/msword;charset=utf-8'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=`CV_MKLEAN_${c.name.replace(/[^a-z0-9]+/gi,'_')}.doc`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('CV MKLEAN téléchargé.');
}
function candidateReportHtml(c){
 const tests=db.assessments.filter(x=>x.candidateId===c.id);
 const refs=c.references||[];
 const pipeline=db.pipeline.filter(x=>x.candidateId===c.id).map(x=>({p:x,j:getJ(x.jobId)}));
 return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Rapport final MKLEAN - ${E(c.name)}</title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;color:#18324d;line-height:1.45;margin:0}header{border-bottom:4px solid #087dcc;padding-bottom:18px;margin-bottom:22px}h1{font-size:28px;color:#0b355b;margin:0}h2{font-size:15px;color:#087dcc;border-bottom:1px solid #d9e8f3;padding-bottom:6px;margin:24px 0 10px}.meta{color:#65788c;font-size:12px;margin-top:5px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#f1f8fc;border-radius:8px;padding:12px}.metric small{display:block;color:#71869a}.metric strong{font-size:20px;color:#087dcc}.item{border-bottom:1px solid #e6edf2;padding:9px 0}.item strong{display:block}.item small{color:#71869a}.status{display:inline-block;background:#e7f6ef;color:#0b9875;border-radius:12px;padding:3px 8px;font-size:10px;font-weight:bold}.note{background:#fff8e8;border:1px solid #f4e5bd;padding:10px;border-radius:8px;font-size:11px;color:#7d6b3d}footer{margin-top:30px;color:#93a1ad;font-size:10px}</style></head><body><header><h1>${E(c.name)}</h1><div class="meta"><strong>${E(c.role)}</strong> · ${E(c.city)} · ${c.experience} ans d'expérience</div><div class="meta">${E(c.email)} · ${E(c.phone)}</div></header><div class="grid"><div class="metric"><small>Tests réalisés</small><strong>${tests.length}</strong></div><div class="metric"><small>Références</small><strong>${refs.length}</strong></div><div class="metric"><small>Étapes recrutement</small><strong>${pipeline.length}</strong></div></div><h2>Résumé du profil</h2><p>${E(c.bio)}</p><p><strong>Compétences :</strong> ${E(c.skills.join(' · '))}</p><h2>Résultats des tests</h2>${tests.map(x=>`<div class="item"><strong>${E(x.type||'Évaluation')}</strong><small>${E(x.date||'Date non renseignée')} · ${E(x.result||x.status||'Résultat à compléter')} · ${E(x.status||'')}</small></div>`).join('')||'<p>Aucun test enregistré dans le dossier.</p>'}<h2>Prises de références</h2>${refs.map(x=>`<div class="item"><strong>${E(x.name)}${x.company?' — '+E(x.company):''}</strong><small>${E(x.relationship||'Référence professionnelle')} · ${E(x.date||'Date non renseignée')} · Note ${E(x.rating||'—')}/5</small><div>${E(x.comment||'Commentaire non renseigné')}</div></div>`).join('')||'<p>Aucune prise de référence enregistrée.</p>'}<h2>Processus de recrutement</h2>${pipeline.map(({p,j})=>`<div class="item"><strong>${E(j?.title||'Offre non renseignée')}</strong><small>${E(j?.company||'Entreprise non renseignée')} · ${E(p.stage)} · ${E(j?.city||'')}</small></div>`).join('')||'<p>Aucune étape de recrutement enregistrée.</p>'}<div class="note">Rapport généré par MKLEAN Talent AI. Les résultats et informations présentés doivent être relus et validés par un responsable du recrutement. Aucune décision automatisée n’est produite par ce rapport.</div><footer>Rapport final candidat · MKLEAN Talent AI · ${today}</footer></body></html>`;
}
function printCandidateReport(c){
 const win=window.open('','_blank','noopener,noreferrer,width=900,height=700');
 if(!win){toast('Autorisez les fenêtres pop-up pour générer le rapport PDF.');return}
 win.document.write(candidateReportHtml(c));win.document.close();win.focus();setTimeout(()=>win.print(),350);toast('Rapport final prêt à être enregistré en PDF.');
}
function htmlForm(form){return Object.fromEntries(new FormData(form).entries())}
function createCandidate(fields,fromImport=false){const id=Math.max(0,...db.candidates.map(x=>x.id))+1;const name=String(fields.name||'Nouveau candidat').trim();const c={id,name,initials:name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase(),role:String(fields.role||'Professionnel'),city:String(fields.city||'Marrakech'),experience:Number(fields.experience)||0,education:String(fields.education||'À renseigner'),skills:String(fields.skills||'').split(',').map(s=>s.trim()).filter(Boolean),status:'À vérifier',validated:false,imported:today,email:'non-renseigne@exemple.test',phone:'Non renseigné',source:fromImport?'Import de démonstration':'Saisie manuelle',bio:String(fields.bio||'Profil créé dans la version de démonstration.'),journey:[]};db.candidates.push(c);save();return c}
