function ensureExtra(){
 db.candidates.forEach((c,i)=>{if(!c.tags)c.tags=[c.role.split(' ')[0],...c.skills.slice(0,2)];if(!c.references)c.references=[];if(!c.recruiter)c.recruiter=['Yasmine','Omar','Sara','Mehdi'][i%4];if(!c.updatedAt)c.updatedAt=c.imported;if(!c.reportStatus)c.reportStatus='À préparer'});
 if(!db.interviewGuides)db.interviewGuides=[{id:1,name:'Guide développeur Full Stack',company:'Atlas Digital',role:'Développeur Full Stack',questions:['Présentez une architecture que vous avez conçue.','Comment sécurisez-vous une API ?','Comment travaillez-vous en équipe ?'],active:true}];
 if(!db.companyEvaluations)db.companyEvaluations=[];
 const props={companies:demoCompanies,interviews:demoInterview,signals:demoSignals,assessments:demoAssessments,placements:demoPlacements,studies:[],crmActivities:[],shortlists:[],sectors:demoSectors,consentLogs:[],marketPrefs:{sector:'all',region:'Toutes les régions',referential:'HCP NMA 2010',period:'2026',type:'sector'},assessPrefs:{test:'Aptitude · Raisonnement logique',candidateId:1}};
 Object.entries(props).forEach(([k,v])=>{if(!Array.isArray(db[k])&&k!=='marketPrefs'&&k!=='assessPrefs')db[k]=structuredClone(v);if((k==='marketPrefs'||k==='assessPrefs')&&!db[k])db[k]=structuredClone(v)});
 db.candidates.forEach((c,i)=>{if(!c.mobilityStatus)c.mobilityStatus=['Actif','À l’écoute','Passif','Indisponible'][i%4]; if(!c.communicationStatus)c.communicationStatus=i%6===0?'Sans réponse':'Joignable';if(!c.consentStatus)c.consentStatus=i%7===0?'À confirmer':'Autorisé'});
 db.jobs.forEach((j,i)=>{if(!j.companyId)j.companyId=(i%demoCompanies.length)+1; if(!j.company)j.company=demoCompanies.find(c=>c.id===j.companyId)?.name||jobCompanies[i%jobCompanies.length]; if(!j.expiresAt)j.expiresAt=`2026-12-${String(10+i*3).padStart(2,'0')}`; if(!j.urgency)j.urgency=jobUrgencies[i%jobUrgencies.length]; if(!j.sector)j.sector=demoCompanies.find(c=>c.id===j.companyId)?.sector||'J'});
}
