 if(act.startsWith('match-candidate:')){ui.selectedCompare=[Number(act.split(':')[1])];navigate('/matching');return}
 if(act.startsWith('match-job:')){ui.matchJob=Number(act.split(':')[1]);ui.selectedCompare=[];navigate('/matching');return}
 if(act==='compare'){openModal({kind:'compare'});return}
 if(act.startsWith('smart-example:')){ui.smartSearch=act.slice(14);ui.searchApplied=ui.smartSearch;render();return}
 if(act==='new-pipeline'){openModal({kind:'new-pipeline'});return}
 if(act.startsWith('approve-source:')){const [,id,key]=act.split(':');db.approvedSources[id]||=[];const arr=db.approvedSources[id];if(arr.includes(key))arr.splice(arr.indexOf(key),1);else arr.push(key);save();render();toast('État de validation mis à jour (démo).');return}
 if(act==='simulate-sources'){toast('4 sources fictives proposées pour validation. Aucune recherche web réelle.');return}
 if(act==='choose-files'){$('#cv-files')?.click();return}
 if(act==='import-next'){if(ui.importStep<4){ui.importStep++;render()}return}
 if(act==='import-back'){ui.importStep=Math.max(1,ui.importStep-1);render();return}
 if(act==='import-reset'){ui.importStep=1;ui.importFiles=[];ui.importValues={};render();return}
