 if(act.startsWith('settings-tab:')){ui.settingsTab=act.split(':')[1];render();return}
 if(act.startsWith('toggle-setting:')){const k=act.split(':')[1];db.settings[k]=!db.settings[k];save();render();toast('Préférence enregistrée localement.');return}
 if(act==='reset-demo'){openModal({kind:'confirm-reset'});return}
